(window.__BOOKS=window.__BOOKS||{})["e_heraclidae"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Иолай, племянник Геракла (1)</span>"],["person","<span class=\"pn\">Копрей, глашатай <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор марафонских поселян</span>"],["person","<span class=\"pn\">Демофонт, афинский царь</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Макария, дочь Геракла</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Слуга Гилла, старшего сына Геракла</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Алкмена, мать Геракла, бабка Гераклидов</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Еврисфей, микенский царь</span> <span class=\"act-no\">(I)</span>"],["place","Действие происходит в Марафоне (в Аттике)"],["act","Пролог","a1",""],["sd","Фон сцены образует храм Зевса на границе между областями Афинской и Марафонской. Перед ним его алтарь, вокруг которого расположились, с зелеными ветвями в руках, малолетние Гераклиды. Они одеты в хитоны и плащи пепельного цвета, как скорбящие. Ближе к зрителям, погруженный в грустное раздумье, старый <span class=\"ch\" data-ch=\"iolay\">Иолай</span>."],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Додумался давно я до сознанья,",0,1,0,0],["v","Что праведный для ближнего рожден.<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,1,0,0],["v","Напротив, кто корыстию охвачен —",0,1,0,0],["v","Нет от такого городу поддержки;",0,2,0,0],["v","С ним тяжело и ведаться: себя",0,3,0,0],["v","Лишь бережет он. Не со слов чужих",0,4,0,0],["v","Сужу об этом. Как покойно б мог я",0,5,0,0],["v","Жить в Аргосе! Но нет: любовь, и честь,",0,6,0,0],["v","И память о родстве хранил я свято —",0,7,0,0],["v","И вот, покуда с нами жил Геракл,",0,8,0,0],["v","Его труды делил я, как никто;",0,9,0,0],["v","Теперь он в горних — я же охраняю",0,10,0,1],["v","Крылом его детей, пожалуй, сам",0,11,0,0],["v","Нуждаяся в охране.",0,12,0,0],["v","Казни нашей,",1,12,0,0],["v","Едва отец их умер, <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span>",0,13,0,0],["v","Потребовал, но безуспешно: жизни —",0,14,0,0],["v","Изгнание спасло нам. С той поры",0,15,0,0],["v","Мы города меняем, бесприютны…",0,16,0,0],["v","И <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span> придумал муки нам",0,17,0,0],["v","Украсить униженьем. Где бы угол",0,18,0,0],["v","Мы ни нашли, — уже послы его",0,19,0,0],["v","Нас требуют, нас гонят; то аргосской",0,20,0,1],["v","Грозят они хозяину враждой,",0,20,0,0],["v","То дружбою его великой манят,",0,21,0,0],["v","Ссылался на то, что <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span> —",0,22,0,0],["v","Могучий царь. Хозяин видит старца",0,23,0,0],["v","Бессильного, детей-сирот — и нас",0,24,0,0],["v","Властителю в угоду изгоняет.",0,25,0,0],["v","Скитания делю и я с детьми,",0,25,0,0],["v","Я муку их делю, блюдя им верность.",0,26,0,0],["v","Не ждать же мне, что скажет кто-нибудь:",0,27,0,0],["v","\"И видно, что Геракла нет: роднею",0,28,0,0],["v","Приходится сиротам <span class=\"ch\" data-ch=\"iolay\">Иолай</span>, —",0,29,0,0],["v","А помощи небось им не окажет…\"",0,30,0,1],["v","Отвергнуты Элладой целой, здесь,",0,31,1,0],["v","У алтарей сидим мы марафонских,",0,32,0,0],["v","Богов моля о помощи. Страну",0,33,0,0],["v","Тесеевы два сына получили,",0,34,0,0],["v","Как долю из наследья Пандиона.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,35,0,0],["v","В них кровь одна с Геракловым потомством;<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,36,0,0],["v","И вот зачем к Афин пределу славных",0,37,0,0],["v","Мы подошли, под Марафона сень.",0,38,0,0],["v","Нас двое воевод, и оба старых:",0,39,0,0],["v","Я опекаю сыновей Геракла,",0,40,0,1],["v","А дочерей — их бабка бережет",0,40,0,0],["v","Под кровом храма этого, <span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>.",0,41,0,0],["v","Нельзя девиц пускать в толпу, сажать",0,42,0,0],["v","Боимся их у алтаря мы даже.",0,43,0,0],["v","Из сыновей же старший, Гилл, и те,",0,44,0,0],["v","Что возрастом ему поближе, вышли",0,45,0,0],["v","На поиски угла, куда склонить",0,45,0,0],["v","Нам голову, коль силой и отсюда",0,46,0,0],["v","Нас удалят…",0,47,0,0],["v","О дети, дети, живо!..",1,47,0,0],["v","Сюда, ко мне, держитесь за меня…",0,48,0,0],["v","Глашатай <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span>! Царь микенский<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,49,0,0],["v","По всей земле гоняет нас!..",0,50,0,1],["v","Чума!",1,50,0,0],["v","Ты сгинешь ли, и царь, тебя пославший,",0,50,0,0],["v","С тобою! Ненавистный, сколько раз",0,51,0,0],["v","Твои уста и славному отцу,",0,52,0,0],["v","И им уже страданье возвещали!",0,53,0,0],["scene","Явление второе","s2",1,2],["sd","Со стороны чужбины появляется Копрей с глашатайским жезлом в правой руке."],["sp","Копрей"],["v","Ты думаешь, конечно, что нашел",0,54,0,0],["v","Убежище надежное и город",0,55,0,0],["v","Союзников… но ты ошибся! Кто",0,56,0,0],["v","Не предпочтет тебе, старик и дряхлый,",0,57,0,0],["v","Такого друга, как аргосский царь!",0,58,0,0],["v","Все хлопоты напрасны. В путь скорей!",0,59,0,0],["v","Заждался град каменьев <span class=\"ch\" data-ch=\"iolay\">Иолая</span>!<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,60,0,1],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Ну, нет! Алтарь — защита нам; земля",0,60,0,0],["v","Свободная под нашими ногами!..",0,61,0,0],["sp","Копрей"],["v","К насилию ты приглашаешь нас?",0,62,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Нет, ни меня, ни этих ты не тронешь!",0,63,0,0],["sp","Копрей"],["v","Увидишь сам, что ты плохой пророк…",0,64,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Пока я жив, ты не возьмешь нас силой!",0,65,0,0],["sp","Копрей"],["v","Прочь, говорю… Ты можешь не желать…",0,65,0,0],["v","А все-таки отдашь их: <span class=\"ch\" data-ch=\"evrisfey\">Еврисфею</span>",0,66,0,0],["v","Принадлежат бежавшие рабы…",0,67,0,0],["sd","Направляется к Гераклидам. <span class=\"ch\" data-ch=\"iolay\">Иолай</span> преграждает ему путь. Он его грубо отталкивает; <span class=\"ch\" data-ch=\"iolay\">Иолай</span> падает. Гераклиды с жалобным криком протягивают к кумиру Зевса молитвенные ветви."],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Все жители исконные афинской",0,68,0,0],["v","Земли, спасите нас! У алтаря",0,69,0,0],["v","Кронидова на площади насильем",0,70,0,1],["v","Пятнается повязка на руках",0,71,0,0],["v","Просителей, поруган город древний,",0,72,0,0],["v","Бессмертные унижены! Сюда!..",0,73,0,0],["scene","Явление третье","s3",1,3],["sd","На сцену появляется хор марафонских поселян."],["scene","Вступительная песнь хора","s4",1,4],["sp","Корифей"],["v","Гей, гей! Что за крик окружает",0,74,0,0],["v","Наш алтарь? И какую беду",0,75,0,0],["v","Этот шум откроет?",0,76,0,0],["sp","Хор"],["sd","Строфа О, глядите… слабый старик… На земле простертый… О, горький!.."],["sp","Корифей"],["v","Кто оскорбил тебя, несчастный старец?",0,77,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Вот дерзостный, который силой нас",0,78,0,0],["v","Со ступеней Кронида увлекает…",0,79,0,0],["sp","Корифей"],["v","Откуда ж ты в Четырехградье к нам,<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,80,0,1],["v","О старик? Иль брега Евбеи",0,81,1,0],["v","На ладьях покинул? За море",0,82,1,0],["v","Переплыв, ты сюда явился?",0,83,1,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Не островом питаем, трачу дни;",0,84,0,0],["v","Микены я сменил на землю вашу.",0,85,0,0],["sp","Корифей"],["v","А по имени как старика",0,86,0,0],["v","Величает народ микенский?",0,87,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Соратник я Гераклов, Иолай,",0,88,0,0],["v","И вам мое небезызвестно имя…",0,89,0,0],["sp","Корифей"],["v","Да, я имя слыхал. А птенцы",0,90,0,1],["v","У тебя-то, старик, это чьи ж,",0,91,0,0],["v","Из какого гнезда, на руках?",0,92,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Геракловы, о чужестранцы; вместе",0,93,0,0],["v","Со мной они вас умолять пришли…",0,94,0,0],["sp","Хор"],["sd","Антистрофа Но о чем? В беседу вступить Ты с гражданством жаждешь афинским?"],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Мы не хотим, чтобы насильем нас",0,95,0,0],["v","От алтарей влачили этих в Аргос.",0,96,0,0],["sp","Копрей"],["v","Но для господ, которые нашли",0,97,0,0],["v","Вас здесь, — увы! — причины эти слабы!",0,100,0,1],["sp","Корифей"],["v","И все-таки молящего уважь!",0,100,0,0],["v","Ты не должен рукою дерзкой",0,101,0,0],["v","Ступеней алтарных касаться:",0,102,0,0],["v","Не потерпит богиня Правда…",0,103,0,0],["sp","Копрей"],["v","Так возврати царю его людей,",0,104,0,0],["v","И воздержусь я тотчас от насилья.",0,105,0,0],["sp","Корифей"],["v","Но безбожно бы было гостей",0,106,0,0],["v","Оттолкнуть молящие руки…",0,107,0,0],["sp","Копрей"],["v","Для города — держаться в стороне",0,108,0,0],["v","От разных осложнений — нет решенья",0,109,0,0],["v","Разумнее, мне кажется… Итак,<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,110,0,1],["v","Детей я уведу, а вы — потише!",0,110,0,0],["sp","Корифей"],["v","На это ты отважишься не раньше,",0,111,0,0],["v","Чем объяснив властителю земли,",0,112,0,0],["v","Зачем ты здесь; покуда ж чужеземцев",0,113,0,0],["v","Не трогай, гость, свободный край почти!",0,113,0,0],["sp","Копрей"],["v","А кто ж царит над городом и краем?",0,114,0,0],["sp","Корифей"],["v","Сын честного Тесея, <span class=\"ch\" data-ch=\"demofont\">Демофонт</span>.",0,115,0,0],["sp","Копрей"],["v","Да, с ним бы мне и надо было спорить —",0,116,0,0],["v","Был на ветер весь с вами разговор.",0,116,0,0],["sd","Нехотя отходит в сторону. Пауза ожидания, заполняемая немой беседой <span class=\"ch\" data-ch=\"iolay\">Иолая</span> с хором."],["sp","Корифей"],["v","А вот и царь; с ним брата Акаманта",0,117,0,0],["v","Я вижу; как поспешны их шаги!..",0,118,0,0],["v","Пускай тебя послушают владыки…",0,119,0,0],["act","Действие первое","a2","I"],["scene","Явление третье","s5",2,5],["sd","Входит царь <span class=\"ch\" data-ch=\"demofont\">Демофонт</span> в сопровождении брата Акаманта и свиты."],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["dir","к Корифею"],["v","Ты упредил, старик, и молодых,",0,120,0,1],["v","Спеша к огню Кронидову; какое ж",0,120,0,0],["v","Событие собрало здесь толпу?",0,121,0,0],["sp","Корифей"],["v","Геракловы птенцы алтарь венчают",0,122,0,0],["v","Мольбой своих ветвей, а возле них,",0,123,0,0],["v","О государь, оруженосец верный",0,124,0,0],["v","Покойного отца их, Иолай…",0,125,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Но этот плач пронзительный с чего же?",0,125,0,0],["sp","Корифей"],["v","Вот этот муж хотел от очага",0,126,0,0],["v","Их увести насильно: он и вызвал",0,127,0,0],["v","Все крики, царь, он старика подшиб,",0,128,0,0],["v","Старик упал… до слез мне был он жалок.",0,129,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["dir","строго смотря на Копрея"],["v","Но, по одеждам судя и тому,",0,130,0,1],["v","Как он их носит, это эллин… Странно!",0,130,0,0],["v","Он поступил как варвар.<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,131,0,0],["sd","(Обращаясь к Копрею.)"],["v","За тобой",0,132,4,0],["v","Я очередь оставил, и не медли:",0,132,0,0],["v","Пожаловал откуда, объясни…",0,133,0,0],["sp","Копрей"],["v","Аргосец я — ты это знать желаешь?",0,134,0,0],["v","А от кого я послан и зачем,",0,135,0,0],["v","Я это сам тебе хочу поведать…",0,135,0,0],["v","Микенский царь сюда нас, Еврисфей,",0,136,0,0],["v","За ними вот направил; а для действий",0,137,0,0],["v","И слов моих, о чужеземец, есть",0,137,0,0],["v","Немало оснований, и законных:",0,138,0,0],["v","Я в качестве аргосца увожу",0,139,0,0],["v","Аргосцев же, которые решеньем",0,140,0,1],["v","Моей земли на казнь осуждены",0,140,0,0],["v","И не дают исполнить приговора.",0,141,0,0],["v","Свои у нас законы, и дела",0,142,0,0],["v","Мы, кажется, решать могли бы сами…",0,143,0,0],["v","Бежавшие у очагов иных",0,144,0,0],["v","Убежища искали уж, и то же,",0,145,0,0],["v","Что слышишь ты теперь, по городам",0,145,0,0],["v","Мне объяснять иным уж приходилось;",0,146,0,0],["v","Желания не выразил никто",0,147,0,0],["v","Своей беды прибавить к злоключеньям",0,148,0,0],["v","Аргосских беглецов; но иль слепцом",0,149,0,0],["v","Они тебя считают, или просто",0,150,0,1],["v","С отчаянья на смелый шаг решились,",0,150,0,0],["v","Не думая, удастся ль им иль нет.",0,151,0,0],["v","Ведь странно же надеяться, что, разум",0,152,0,0],["v","Не потеряв, решишься ты один",0,152,0,0],["v","Перед лицом Эллады равнодушной",0,153,0,0],["v","К их безрассудной доле снизойти…",0,154,0,0],["v","Ты только взвесь, чт<em>о</em> выгодней тебе:",0,155,1,0],["v","Впустить ли в землю их иль нам дозволить",0,155,0,0],["v","Их увести. От нас тебе награда —",0,156,0,0],["v","Всего поддержка Аргоса, союз",0,157,0,0],["v","С могучим <span class=\"ch\" data-ch=\"evrisfey\">Еврисфеем</span>. А размякни",0,157,0,0],["v","От жалоб ты и слов их — и войну",0,158,0,0],["v","Ты навязал себе на шею. Разве",0,159,0,0],["v","Ты думаешь, что мы окончим спор,",0,160,0,1],["v","Не подкрепив желаний звоном меди?",0,160,0,0],["v","И что ж своим ты скажешь? Где поля,",0,161,0,0],["v","Которых ты лишен? Каких мы граждан",0,162,0,0],["v","В полон афинских увели? Какие",0,162,0,0],["v","Союзники твоей защиты просят?",0,163,0,0],["v","Похоронить придется столько тел",0,164,0,0],["v","На поле брани павших — и за что же?",0,165,0,0],["v","Да, граждане тебя благодарить",0,165,0,0],["v","Не будут за причину столкновенья;",0,166,0,0],["v","Старик, который в гроб глядит, ничто,",0,167,0,0],["v","И ребятишки эти… и за ними",0,167,0,0],["v","Ты хочешь в омут? Лучшее всегда",0,168,0,0],["v","Надежда нам рисует; но, поверь мне,",0,169,0,0],["v","И лучшему в надеждах не легко",0,170,0,1],["v","Сравняться с настоящим. Эти дети,",0,170,0,0],["v","Доросши до доспехов, не смогли б",0,171,0,0],["v","Аргосцев одолеть, коли надеждой",0,172,0,0],["v","На это окрылен ты; а покуда",0,173,0,0],["v","Они растут, успеете вы все",0,173,0,0],["v","Погибнуть… Нет! Послушайся… Не должен",0,174,0,0],["v","Ты отдавать своих вещей, — позволь,",0,175,0,0],["v","Чтоб мы лишь наше взяли, и Микены —",0,176,0,0],["v","Твои. Не будь народу своему",0,176,0,0],["v","Подобен, царь, предпочитая слабых,",0,177,0,0],["v","Когда к тебе идет могучий друг!..<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,178,0,0],["sp","Корифей"],["v","Не выслушав обоих, приговора<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,179,0,0],["v","Произносить не должен ты, судья!",0,180,0,1],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Царь, в этом ведь страны твоей краса:",0,180,0,0],["v","На слово словом здесь ответить равным",0,181,0,0],["v","Позволят мне и не велят в молчанье —",0,182,0,0],["v","Как в городах иных — оставить край.",0,183,0,0],["v","У нас же с этим мужем общих уз",0,184,1,0],["v","Уж нет. Ведь города постановленьем",0,185,0,0],["v","Мы изгнаны, мы не микенцы боле —",0,186,0,0],["v","Откуда же права его на нас?",0,187,0,0],["v","Мы — чужестранцы для него. Иль тот,",0,188,0,0],["v","Кто Аргосом был изгнан, сразу должен",0,189,0,0],["v","Изгнанником для всей Эллады быть?",0,190,0,1],["v","Не для Афин же, царь; аргосский страх",0,190,0,0],["v","Вас не заставит сыновей Геракла",0,191,0,0],["v","Изгнать; ведь не в Трахине мы, не в граде",0,192,0,0],["v","Страны ахейской, из которой ты, —",0,193,0,0],["v","Не правдой, нет, а Аргосом пугая, —",0,194,0,0],["v","Изгнанья их добиться, точно, мог,",0,195,0,0],["v","Хоть алтари молящих осеняли…",0,196,0,0],["v","Коль ты и здесь того ж добьешься, нет",0,197,0,0],["v","Афин свободных больше. Но я знаю",0,198,0,0],["v","Их чувства, их природу: умереть",0,199,0,0],["v","Афиняне скорей бы согласились;",0,200,0,1],["v","Ведь благородный человек и жизни",0,200,0,0],["v","Не выкупит позором…",0,201,0,0],["v","Но довольно",1,201,0,0],["v","О городе: ведь в похвалах претит",0,202,0,0],["v","Излишество — по опыту я знаю,",0,203,0,0],["v","И частому, всю тяжесть похвалы,",0,204,0,0],["v","Когда она чрезмерна. Лучше будет,",0,205,0,0],["v","Коль разъясню тебе я, почему,",0,205,0,0],["v","Как царь Афин, ты выручить их должен.",0,206,0,0],["v","Питфей был сын Пелопа; от него",0,207,0,0],["v","Мать твоего отца Тесея, Эфра,",0,208,0,0],["v","Произошла. Теперь мы проследим,",0,209,0,0],["v","Откуда Гераклиды. Был <span class=\"ch\" data-ch=\"alkmena\">Алкменой</span>",0,210,0,1],["v","От Зевса их рожден отец; она",0,210,0,0],["v","Дочь дочери Пелопа; твой родитель",0,211,0,0],["v","Троюродным отцу их братом был,",0,212,0,0],["v","Царь <span class=\"ch\" data-ch=\"demofont\">Демофонт</span>…",0,213,0,0],["v","Но и помимо уз,",1,213,0,0],["v","Скажу тебе, что ты у Гераклидов",0,213,0,0],["v","Еще в долгу. Ведь сам оруженосцем",0,214,0,0],["v","Я у Геракла был, когда в поход",0,215,0,0],["v","С Тесеем он собрался, чтобы пояс",0,216,0,0],["v","Добыть — побед бесчисленных залог.",0,216,0,0],["v","Геракл затем из глубины Аида",0,217,0,0],["v","Бессветной вырвал твоего отца:",0,218,0,0],["v","Так молвит вся Эллада. Заплати ж",0,219,0,0],["v","Им милостью за это, царь: молящих",0,220,0,1],["v","Врагам не выдай, не дозволь злодеям,",0,220,0,0],["v","Наперекор богам твоим, из края",0,221,0,0],["v","Их увести. Какой позор бы был",0,222,0,0],["v","Афинскому царю, когда б скитальцы, —",0,223,0,0],["v","Молящие, его родные, — силой",0,223,0,0],["v","От алтарей увлечены бы были…",0,224,0,0],["v","О, погляди на них, хоть погляди,",0,225,0,0],["v","Как жалок вид их, умоляю!.. Руки",0,226,0,0],["v","Тебя с мольбой обвили; бороды",0,226,0,0],["v","Касаясь, заклинаю <span class=\"ch\" data-ch=\"demofont\">Демофонта</span>, —",0,227,0,0],["v","Не отдавай в обиду сыновей",0,228,0,0],["v","Геракловых, прими их, будь родным",0,229,0,0],["v","И другом их, явись отцом, иль братом…",0,230,0,1],["v","Иль господином даже; ведь и это",0,230,0,0],["v","Для сирых лучше, чем аргосский меч.",0,231,0,0],["sp","Корифей"],["v","Как жалостна их участь, государь!",0,232,0,0],["v","Я никогда не видел, чтоб судьбой",0,232,0,0],["v","Был более унижен благородный!",0,233,0,0],["v","Отцовское не охранило их",0,234,0,0],["v","От незаслуженных страданий имя!",0,235,0,0],["sd","Во время этих слов <span class=\"ch\" data-ch=\"demofont\">Демофонт</span> тихо совещается с Акамантом, теперь он обращается к <span class=\"ch\" data-ch=\"iolay\">Иолаю</span>."],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Мне указуют путь твой, Иолай,",0,235,0,0],["v","Три довода, отвергнуть не давая",0,236,0,0],["v","Твоих сирот. Превыше всех — Зевеса",0,237,0,0],["v","Я чту алтарь, который осенил",0,237,0,0],["v","Тебя с птенцами этими… Затем",0,238,0,0],["v","Идет родство и их отца услуга,",0,239,0,0],["v","Которую должны мы оплатить",0,240,0,1],["v","Его семье… Но если что волнует",0,240,0,0],["v","Меня, то это — высший довод: честь.",0,241,0,0],["v","Ведь если я позволю, чтобы силой",0,242,0,0],["v","От алтаря молящих отрывал",0,242,0,0],["v","Какой-то иноземец, так прощай",0,243,0,0],["v","Афинская свобода! Всякий скажет,",0,244,0,0],["v","Что из боязни Аргоса — мольбу",0,244,0,0],["v","Изменой оскорбил я. Хуже петли",0,245,0,0],["v","Сознание такое. Да, с тобой",0,246,0,0],["v","Мы встретились при грустной обстановке,",0,246,0,0],["v","Но все-таки не трепещи: насильем",0,247,0,0],["v","Не будете уведены ни ты,",0,248,0,0],["v","Ни эти дети…",0,248,0,0],["sd","(К Копрею.)"],["v","Ты ж отправься в Аргос",0,249,4,0],["v","И <span class=\"ch\" data-ch=\"evrisfey\">Еврисфею</span> это объяви;",0,250,0,1],["v","Прибавь, что если в чем он обвиняет",0,250,0,0],["v","Пришельцев — правды путь ему у нас",0,251,0,0],["v","Открыт; но увести их ты не смеешь.",0,252,0,0],["sp","Копрей"],["v","А если прав я? Если б ты склонился?",0,253,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Ты прав — молящих уводя насильно?",0,254,0,0],["sp","Копрей"],["v","Ну, мне и стыдно будет, не тебе ж…",0,255,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Нет, мне, раз я насилье допускаю…",0,255,0,0],["sp","Копрей"],["v","Ты выстави их только за предел",0,256,0,0],["v","Твоей земли, а там уж наше дело!",0,257,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Перехитрить богов? Совет не умный!",0,258,0,0],["sp","Копрей"],["v","Ты наберешь в Афины негодяев!",0,259,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Для всех людей защита — алтари.",0,260,0,1],["sp","Копрей"],["v","Не убедят слова твои микенцев!",0,261,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Но у себя дела решаю я.",0,262,0,0],["sp","Копрей"],["v","Разумен будь — микенцев не гневи!",0,263,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Пусть лучше вас гневлю я, но не бога.",0,264,0,0],["sp","Копрей"],["v","С Микенами войны вам не желаю.",0,265,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Зачем войны? Но не отдам гостей…",0,266,0,0],["sp","Копрей"],["dir","с угрожающим движением"],["v","Я увожу своих — не помешаешь?..",0,267,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Попробуешь, — но с Аргосом простись…",0,268,0,0],["sp","Копрей"],["v","А вот сейчас попробуем — посмотрим…",0,269,1,0],["sd","(Хватает ближайшего Гераклида. Крик.)"],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Смотри, придется плакать — и сейчас!<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,270,0,1],["sd","(Гневно отталкивает Копрея и вырывает у него мальчика. Смятение в хоре.)"],["sp","Корифей"],["v","Ради богов! Глашатая не бей!",0,270,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","А если долг глашатай нарушает?",0,271,0,0],["sp","Корифей"],["dir","к Копрею"],["sd","Уйди, уйди… (К <span class=\"ch\" data-ch=\"demofont\">Демофонту</span>.) А ты посла не трогай!"],["sp","Копрей"],["v","Я ухожу. Что сделаешь один?",0,272,0,0],["v","Но я вернусь с аргосскою дружиной.",0,273,0,0],["v","Доспехи ей Арес ковал, и ждут",0,274,0,0],["v","Нас тысячи аргосцев, опираясь",0,275,0,0],["v","На тяжкие щиты. Сам <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span>",0,275,0,0],["v","Ведет их в бой. Царь выдвинул дружины",0,276,0,0],["v","На грань земли мегарской, чтоб от нас",0,277,0,0],["v","Скорей узнать исход посольства. Пусть",0,278,0,0],["v","Услышит он про эту наглость, — будем",0,279,0,0],["v","Мы памятны тебе, и сонму граждан,<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,280,0,1],["v","И всей земле, и насажденьям вашим…",0,280,0,0],["v","Зачем тогда и юношей растить",0,281,0,0],["v","Нам тысячи в Микенах, коли даром",0,282,0,0],["v","Сходило бы врагам глумленье их!..",0,282,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Иди и сгинь, твой Аргос мне не страшен.",0,283,0,0],["v","А этому не быть, чтоб опозорить",0,284,0,0],["v","Себя я дал, дозволив вам гостей",0,285,0,0],["v","Своих увесть. Не подчинен Аргосу",0,285,0,0],["v","Мой город, нет: свободен он всегда.",0,286,0,0],["scene","Явление четвертое","s6",2,6],["sd","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span> с Акамантом, Иолай, Гераклиды и хор. Цари смотрят вслед ушедшему Копрею и озабоченно совещаются."],["sp","Корифей"],["v","Время не терпит… Пока",0,287,0,0],["v","К нашим пределам враги",0,287,0,0],["v","Не подступили… решить",0,288,0,0],["v","Многое надо; могуч",0,289,0,0],["v","Был у микенцев Арес —",0,290,0,1],["v","Стал он теперь и свиреп…",0,290,0,0],["v","Ведь у герольда в устах",0,291,0,0],["v","Что ни огонь, то пожар…",0,292,0,0],["v","Он ли в рассказе царям",0,293,0,0],["v","Не разукрасит обид?..",0,294,0,0],["v","Скажет: \"Едва я ушел,",0,295,0,0],["v","Смертью грозили послу!..\"",0,295,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["dir","обращаясь к детям"],["v","Нет для детей отрадней дара, если",0,296,0,0],["v","Они отцом и добрым рождены",0,297,0,0],["v","И знатным и от матери такой же.",0,298,0,0],["v","Но если муж, желаньем покорен,",0,299,0,0],["v","Берет жену безродную, — услада",0,300,0,1],["v","Отцовская позором остается",0,300,0,0],["v","Его семье. Удар судьбы — и тот",0,301,0,0],["v","Скорее отразит благорожденный,",0,302,0,0],["v","Чем тот, кто родом низок. Мы дошли",0,303,0,0],["v","До крайней точки бедствия — и все же",0,303,0,0],["v","Нашли себе друзей и братьев — их:",0,304,0,0],["v","Они одни в Элладе многолюдной",0,305,0,0],["v","Нас защитить решились и спасти.",0,306,0,0],["v","Приблизьтесь, дети, протяните им",0,306,0,0],["v","Вы руки правые — и вы, селяне,",0,307,0,0],["v","Их приголубьте!",0,308,0,0],["sd","Гераклиды спускаются со ступеней алтаря; марафонцы идут им навстречу и обнимают их по очереди. Последними их ласкают <span class=\"ch\" data-ch=\"demofont\">Демофонт</span> и Акамант. Во время этой сцены <span class=\"ch\" data-ch=\"iolay\">Иолай</span> продолжает свое слово."],["v","Да, друзей, родные,",1,308,0,0],["v","Открыл тяжелый опыт. Коль возврата",0,309,0,0],["v","В удел отца дождетесь вы и дом",0,310,0,1],["v","И честь его вернете, почитайте",0,310,0,0],["v","Спасителей в царях земли афинской",0,311,0,0],["v","Навеки и друзей. И вот завет",0,311,0,0],["v","Мой, дети, вам: чтоб вражеским копьем",0,312,0,0],["v","Вы никогда их землю не громили, —",0,313,0,0],["v","Нет, меж союзных чтили самой близкой…",0,313,0,0],["v","Венчайте уважением мужей,",0,314,0,0],["v","Которые из-за бездомных нищих",0,315,0,0],["v","Себе врагов бесчисленных добыть<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,315,0,0],["v","И сильных не задумались в пеласгах,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,316,0,0],["v","Которые не выдали детей",0,316,0,0],["v","Геракловых и не прогнали.",0,317,0,0],["sd","(К <span class=\"ch\" data-ch=\"demofont\">Демофонту</span>.)"],["v","Я же,",0,318,4,0],["v","Пока я жив, да и по смерти, друг,",0,318,0,0],["v","Хвалой тебя перед далекой тенью",0,319,0,0],["v","Тесея возвеличу, услаждая",0,320,0,1],["v","Ее рассказом о тебе. Как друг,",0,321,0,0],["v","Ты принял нас, пригрел детей Геракла,",0,322,0,0],["v","И отчую в Элладе славу ты,",0,323,0,0],["v","Афинский царь, сберег. Тебя родившим",0,324,0,0],["v","Не уступил ты в доблести — таких",0,325,0,0],["v","Немного ведь. Один на сотню разве",0,326,0,0],["v","Достоинством отцу подобен сын.<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,327,0,0],["sp","Корифей"],["v","Не в первый раз стоять земле афинской",0,328,0,0],["v","За правду и несчастных; без числа",0,330,0,1],["v","Она подъяла бед в борьбе за друга…",0,330,0,0],["v","Такое ж состязанье предстоит…",0,331,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["dir","к <span class=\"ch\" data-ch=\"iolay\">Иолаю</span>"],["v","Ты хорошо сказал, и я уверен,",0,332,0,0],["v","Что так с детьми и будет: о моей",0,333,0,0],["v","Они тогда услуге не забудут…",0,334,0,0],["v","А я иду на совещанье граждан",0,335,0,0],["v","Созвать и тем — дружиною отпор",0,335,0,0],["v","Обильной приготовить; но сначала",0,336,0,0],["v","Лазутчиков пошлю, чтобы врасплох",0,337,0,0],["v","На город не напали, — ведь аргосцы",0,338,0,0],["v","Все на подъем легки; да не забыть",0,339,0,0],["v","Гадателей собрать, устроить жертву…",0,340,0,1],["v","Ты ж во дворец отправься и возьми",0,340,0,0],["v","С собой детей. Очаг не нужен Зевса",0,341,0,0],["v","Моим гостям. Я ухожу, но вас",0,342,0,0],["v","И без меня там примут. С богом, старец!",0,343,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Нет, очага позволь не покидать…",0,344,0,0],["v","Молящие, от алтаря взывая",0,345,0,0],["v","К отцу богов, испросят счастья вам!",0,345,0,0],["v","Когда ж исход борьбы благополучным",0,346,0,0],["v","Окажется — твои мы гости, царь!",0,347,0,0],["v","Да, не слабей аргосских наши боги:",0,348,0,0],["v","Им помогает Гера, что с отцом",0,349,0,0],["v","Бессмертных ложе делит; нам — Афина,",0,350,0,1],["v","И, право ж, это счастье, что она:",0,351,0,0],["v","Паллада без победы не уходит.",0,352,0,0],["sd","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span> и Акамант покидают сцену. <span class=\"ch\" data-ch=\"iolay\">Иолай</span> и Гераклиды располагаются у алтаря."],["scene","Первый музыкальный антракт","s7",2,7],["sp","Хор"],["str","Строфа"],["v","Если кичлив ты, аргосец, —",0,353,0,0],["v","Нам от того не больше,",0,354,0,0],["v","О чужеземец, горя…",0,355,0,0],["v","Грозной своею речью",0,356,0,0],["v","Не ужаснешь ты сердца…",0,357,0,0],["v","Так да не будет великим",0,358,0,0],["v","Хорами славным Афинам,",0,359,0,0],["v","Как говорил ты… безумен",0,360,0,1],["v","Ты и властитель аргосский!",0,361,0,0],["str","Антистрофа"],["v","В город пришел ты свободный,",0,362,0,0],["v","Силой Микенам равный,",0,363,0,0],["v","Чтоб увлекать насильем",0,364,0,0],["v","От алтаря молящих;",0,365,0,0],["v","Сам чужеземец, в чести",0,366,0,0],["v","Ты отказал властелинам,",0,367,0,0],["v","Правды путем пренебрег ты!",0,368,0,0],["v","Может ли быть у разумных",0,369,0,0],["v","Слава деянью такому?",0,370,0,1],["str","Эпод"],["v","Мир мое сердце любит…",0,370,0,0],["v","Все же, злобный владыка,",0,371,0,0],["v","Слушай! В городе нашем",0,372,0,0],["v","Встретишь прием ты немилый.",0,373,0,0],["v","Иль у тебя лишь копья?",0,374,0,0],["v","Войско в доспехах медных",0,375,0,0],["v","Есть и у нас… Хоть друг ты",0,376,0,0],["v","Шуму и сече бранной,",0,377,0,0],["v","Все же совет мой: смуту",0,378,0,0],["v","В город, Харитам милый,",0,379,0,0],["v","Лучше вводить побойся!",0,380,0,1],["act","Действие второе","a3","II"],["scene","Явление пятое","s8",3,8],["sd","Возвращается, глубоко озабоченный, <span class=\"ch\" data-ch=\"demofont\">Демофонт</span>. <span class=\"ch\" data-ch=\"iolay\">Иолай</span> идет ему навстречу."],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Дитя мое, раздумье на лице",0,380,0,0],["v","Написано твоем… Иль об аргосцах",0,381,0,0],["v","Сообщено?",0,382,0,0],["v","Замедлился поход,",1,382,0,0],["v","Иль здесь они? Иль новое услышал",0,383,0,0],["v","Ты что-нибудь? Глашатая слова",0,384,0,0],["v","Неложною угрозою звучали…",0,385,0,0],["v","Царь <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span>, успехом окрылен,",0,386,0,0],["v","Идет на город ваш, и это верно.",0,387,0,0],["v","Но гордых дум не терпит царь богов…",0,388,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Аргосцы здесь, старик, и с <span class=\"ch\" data-ch=\"evrisfey\">Еврисфеем</span>,",0,389,0,0],["v","Сам видел я царя… Ведь если кто",0,390,0,1],["v","Быть воеводой истинным желает,",0,390,0,0],["v","Не вестникам тот верит, а глазам.",0,391,0,0],["v","Но все же он войска свои покуда",0,392,0,0],["v","В равнину не спускает. Он засел",0,393,0,0],["v","На вышине отвесной и, должно быть,",0,394,0,0],["v","Высматривает путь, чтоб без отпора",0,395,0,0],["v","Ему страну полками наводнить",0,396,0,0],["v","И основаться в ней всего вернее.",0,397,0,0],["v","В ответ и мы надежно снарядились:",0,398,0,0],["v","Афиняне в доспехах, и стоят",0,399,0,0],["v","Готовыми для жертвы козы. Всюду",0,400,0,1],["v","Жрецы аргосцам молят лютой смерти,",0,401,0,0],["v","А городу спасенья. Я велел",0,402,0,0],["v","И вещунам собраться; сколько было",0,403,0,0],["v","Таинственных оракулов и явных,",0,404,0,0],["v","Сличили мы, подъявши пыль веков;",0,405,0,0],["v","Немало в них открыли разноречий,",0,406,0,0],["v","Но сходятся в одном гаданья все:",0,407,0,0],["v","Деметриной в усладу дщери грозной",0,408,0,0],["v","Должны мы деву благородной крови",0,409,0,0],["v","Заклать… Ты видишь: вам помочь я рад,",0,410,0,1],["v","Но дочь отдать я не решусь, и странно б",0,410,0,0],["v","Насилием мне было отбирать",0,411,0,0],["v","Рожденную в Афинах от ее",0,412,0,0],["v","Родителей; а кто ж такой безумец,",0,412,0,0],["v","Чтобы зеницу глаз своих охотно",0,413,0,0],["v","На истребленье дать? И так уже",0,414,0,0],["v","Афиняне волнуются, и споры",0,415,0,0],["v","Наш город раздирают: кто со мною",0,415,0,0],["v","Согласен и считает справедливым",0,416,0,0],["v","Молящего почтить, а для иных",0,417,0,0],["v","Мечтатель я. А если крови девы",0,417,0,0],["v","Потребовать осмелюсь я — мятеж",0,418,0,0],["v","Немедля вспыхнет. Что мне делать, старец?",0,419,0,0],["v","Не сыщешь ли ты средства и себя",0,420,0,1],["v","С детьми, и нас спасти, от осуждений",0,420,0,0],["v","Афинского царя освободив?",0,421,0,0],["v","Ведь я не варвар-самодержец: власти",0,422,0,0],["v","Моей постольку граждане покорны,",0,423,0,0],["v","Поскольку сам покорен правде — царь.",0,424,0,0],["sp","Корифей"],["v","Помочь в нужде мы рады чужеземцам",0,425,0,0],["v","Да, видно, бог пути нам преградил.",0,426,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["sd","Во время его речи двери храма приотворяются, и из них выходит <span class=\"ch\" data-ch=\"makariya\">Макария</span>. По всему видно, что она встревожена; она спускается по ступеням храма к Гераклидам, жадно прислушиваясь к словам говорящих."],["v","О дети! Мы теперь, как мореходы,",0,427,0,0],["v","Едва спаслись от яростной волны,",0,428,0,0],["v","До гавани рукой подать, и вдруг",0,429,0,0],["v","Безумный шквал… и где опять тот берег?",0,430,0,1],["v","Земля от нас уходит эта, дети,",0,430,0,0],["v","А славили спасенье мы!.. Себя",0,431,0,0],["v","На суше мы считали… Ты, надежда,",0,432,0,0],["v","Нас радостно дразнила, — для чего ж,",0,432,0,0],["v","Коль милости к несчастным не таила",0,433,0,0],["v","Твоя мечта? Могу ли на царя",0,434,0,0],["v","Я гневаться, что он не отбирает",0,435,0,0],["v","Афинских дев у граждан для ножа?",0,435,0,0],["v","Своей хвалы я не возьму обратно",0,436,0,0],["v","У города. Я все же твой должник,",0,437,0,0],["v","О царь, хоть мой удел и жалок…",0,437,0,0],["v","Только",1,437,0,0],["v","Для вас-то что ж придумаю, птенцы?",0,438,0,0],["v","Куда еще идти? И есть ли боги,",0,439,0,0],["v","Которых бы мольбою не венчал",0,440,0,1],["v","Я алтарей? И где огонь очажный,",0,440,0,0],["v","Который бы детей не озарил",0,441,0,0],["v","Беспомощных?.. Нас выдадут микенцу…",0,442,0,0],["v","И я умру… Ну что ж! Я одного",0,443,0,0],["v","При этом лишь боюсь — его глумлений…",0,444,0,0],["v","Но вас до слез мне жалко, малыши,",0,445,0,0],["v","И старую <span class=\"ch\" data-ch=\"alkmena\">Алкмену</span> тоже жалко…",0,445,0,0],["v","Твой долгий век, о горькая, каким",0,446,0,0],["v","Венчается концом!.. И я, несчастный,",0,447,0,0],["v","Трудился для чего же? Для того ль,",0,448,0,0],["v","Чтобы, врагу попав позорно в руки,",0,449,0,0],["v","Из жизни так печально выбыть?",0,450,0,1],["sd","(Грустно склоняет голову. Пауза размышления. Внезапно он опять выпрямляется, как бы озаренный новой мыслью.)"],["v","Царь,",0,450,4,0],["v","Ты спрашивал, что делать… помоги ж нам",0,451,0,0],["v","Теперь в одном… ведь на спасенье есть",0,452,0,0],["v","Еще надежда детям: <span class=\"ch\" data-ch=\"iolay\">Иолаем</span>",0,453,0,0],["v","Ты замени Геракловых птенцов!..",0,453,0,0],["v","Избегнешь ты опасности, и дети",0,454,0,0],["v","Останутся в живых. А старику",0,455,0,0],["v","Что в жизни за отрада? Бог же с нею!",0,456,0,0],["v","Ведь более всего желал бы он",0,456,0,0],["v","Гераклова соратника унизить:",0,457,0,0],["v","Не благороден он. Молись, разумный,",0,458,0,0],["v","С разумным чтоб вражда тебя свела:",0,459,0,0],["v","Тогда и честь изведаешь и правду.",0,460,0,1],["sp","Корифей"],["v","Ты прав, старик; сними же обвиненье",0,460,0,0],["v","С земли афинской. Иначе падет",0,461,0,0],["v","Укор на нас, хоть лживый, но позорный,",0,462,0,0],["v","Что выдали Микенам мы гостей.",0,462,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","Слова твои при всем их благородстве",0,463,0,0],["v","Нисколько не помогут нам. Сюда",0,464,0,0],["v","Дружину царь не за тобой приводит…",0,465,0,0],["v","И что ему прибавится, — умри",0,465,0,0],["v","Действительно старик? Он хочет смерти",0,466,0,0],["v","Гераклова потомства. Для врагов",0,467,0,0],["v","Опасен благородный, вырастая,",0,467,0,0],["v","Что юношей он станет и отца",0,468,0,0],["v","Припомнит им он униженье. Это",0,469,0,0],["v","И <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span> теперь предвидит, верно…",0,470,0,1],["v","Нет, поищи другое что-нибудь…",0,470,0,0],["v","А я ума не приложу, и страхом",0,471,0,0],["v","Вещания мне сердце наполняют…",0,472,0,0],["scene","Явление шестое","s9",3,9],["sd","К говорящим подходит <span class=\"ch\" data-ch=\"makariya\">Макария</span>. Она в плаще или накидке такого же пепельного цвета, как и прочие Гераклиды. Волосы распущены."],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["v","О, не считайте своевольем, мужи,",0,473,0,0],["v","Что я ушла из храма — вас прошу<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,474,0,0],["v","Об этом с первых слов. Я знаю, девам",0,475,0,0],["v","Молчание и скромность подобают",0,476,0,0],["v","И тишина жилища… Но твои",0,477,0,0],["v","Я услыхала стоны, Иолай,",0,478,0,0],["v","И хоть никто меня из Гераклидов",0,479,0,0],["v","Не посылал, — какой-то голос тайный",0,480,0,1],["v","Увлек меня. За братьев я болею,",0,480,0,0],["v","Да и сама желаю я узнать,",0,481,0,0],["v","Какой удар, в придачу к прежним, новый",0,482,0,0],["v","Тебя поверг в уныние, старик?",0,483,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Тебя всегда, дитя мое, хвалой",0,484,0,0],["v","Среди сестер и братьев отличал я!",0,485,0,0],["v","Наш бог, о дочь, отраду нам сулил,",0,486,0,0],["v","И снова неудача. Этот муж",0,487,0,0],["v","Гадания здесь передал: не телку",0,488,0,0],["v","И не быка Афинам бог велит",0,489,0,0],["v","Для дочери Деметры, а девицу,",0,490,0,1],["v","И благородной крови, заколоть.",0,490,0,0],["v","<span class=\"ch\" data-ch=\"makariya\">Макария</span> вздрагивает.",0,491,0,0],["v","И выхода нет более ни в чем",0,492,0,0],["v","Ни городу, ни нам — иначе гибнем…",0,492,0,0],["v","Вот наше горе, дочь моя; ни царь,",0,493,0,0],["v","Ни гражданин афинский не заколют",0,494,0,0],["v","Своих детей — он это объяснил.",0,495,0,0],["v","А значит… хоть не вымолвил он ясно,",0,495,0,0],["v","Но все же понял я: \"Ищите, мол,",0,496,0,0],["v","Себе иной страны, свои ж Афины",0,497,0,0],["v","Не волен я погибели предать\".",0,497,0,0],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["dir","стараясь побороть внутреннее волнение"],["v","И это — все?.. Условье счастья — в этом?",0,498,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Да; более, дитя, задержки нет…",0,499,0,0],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["dir","решительно"],["v","Тогда врагов и ратников микенских",0,500,0,1],["v","Бояться не должны вы… Умереть",0,500,0,0],["v","Готова я, старик! Сама я горло",0,501,0,0],["v","Подставлю им, покуда мне никто",0,502,0,0],["v","Не приказал еще жрецам отдаться…",0,503,0,0],["v","И что сказать могли бы мы? За нас",0,503,0,0],["v","Афиняне опасностей и муки",0,504,0,0],["v","Подъемлют бремя тяжкое, а нам",0,505,0,0],["v","Есть случай их спасти, и мы боимся",0,506,0,0],["v","Пожертвовать собою… Не смешно ль?",0,506,0,0],["v","Рожденные Гераклом — и в несчастье",0,507,0,0],["v","Умеют только плакать да алтарь",0,508,0,0],["v","С мольбою обнимать, как трусы! Разве",0,509,0,0],["v","Прилично это благородным? Или",0,510,0,1],["v","Для дочери Геракла лучше будет —",0,510,0,0],["v","Из города, который взят копьем",0,511,0,0],["sd","(Не станется ж от слова!), руки вражьи"],["v","Добычею украсить и, позор",0,512,0,0],["v","Вкусивши, в ту ж сойти юдоль Аида?",0,513,0,0],["v","Иль нам уйти отсюда?.. Что ж, опять",0,514,0,0],["v","Скитания да речь еще вдобавок,",0,515,0,0],["v","Которой не слыхали мы: \"Опять",0,515,0,0],["v","Вы с ветками молящих… Что вам надо?",0,516,0,0],["v","Ступайте, жизнелюбцы, вы свою",0,517,0,0],["v","Уж доказали трусость… помогать",0,518,0,0],["v","Вам не хотим мы больше…\" Но надежды",0,519,0,0],["v","На счастие, останься я одна",0,520,0,1],["v","Живой из Гераклидов, тоже нет!",0,520,0,0],["v","А многие в такой надежде друга",0,521,0,0],["v","Предать не побоялись. Кто бы взял",0,522,0,0],["v","В супруги сироту, одну на свете,",0,523,0,0],["v","И захотел бы от меня детей?",0,523,0,0],["v","Не лучше ль умереть, чем этот жребий,",0,524,0,0],["v","Столь недостойный нас! Другой, пожалуй,",0,525,0,0],["v","Он и пристал бы — не в такой рожденной",0,526,0,0],["v","Красе, как я.",0,526,0,0],["v","Веди ж меня туда,",1,526,0,0],["v","Где с жизнью я прощусь… венком украсьте…",0,527,0,0],["v","Волос моих железо пусть коснется,",0,528,0,0],["v","Коль так велит обычай. Но врагам",0,529,0,0],["v","Победы не давайте!.. Душу волей",0,530,0,1],["v","Вам отдаю, никто не приказал,",0,530,0,0],["v","И знайте все, что жертвою за братьев",0,531,0,0],["v","И самое себя я умираю…",0,532,0,0],["v","Я клад прекрасный обрела, любовь",0,533,0,0],["v","Презревши к жизни, — славной смерти клад.",0,534,0,0],["sp","Корифей"],["v","О, что сказать мне? Гордой речи внял я",0,535,0,0],["v","Из уст девичьих: умереть за братьев",0,535,0,0],["v","Она горит. Кто мог бы благородней",0,536,0,0],["v","Промолвить слово иль свершить деянье?",0,537,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Мое дитя, поистине другого",0,538,0,0],["v","Ты не могла быть дочерью, и дух",0,539,0,0],["v","Божественный Геракла вместе с кровью",0,540,0,1],["v","В твое вселился тело!.. Я словам",0,540,0,0],["v","Внимал твоим, гордяся, но судьбою",0,541,0,0],["v","Твоею я смущен. И справедливей",0,542,0,0],["v","Поступим мы, коль соберем сюда",0,543,0,0],["v","Твоих сестер — и пусть решает жребий,",0,543,0,0],["v","Кому идти на смерть за целый род;",0,544,0,0],["v","Отдать тебя, судьбы не испытавши, —",0,545,0,0],["v","То было бы неправдой, дочь моя!..",0,546,0,0],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["v","О нет, оставь, старик… Я не хочу",0,546,0,0],["v","Быть жертвою по жребию: иль этим",0,547,0,0],["v","Стяжала бы любовь я?.. Если ж душу",0,548,0,0],["v","Вы примете мою и умереть",0,549,0,0],["v","Дадите мне за них по вольной воле,",0,550,0,1],["v","Без всякого насилья, — я готова…",0,550,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Еще прекрасней прежнего сказала",0,551,0,0],["v","Ты слово, дева, — хоть и в том явила",0,552,0,0],["v","Ты благородство полное. Дитя,",0,553,0,0],["v","Отвагою отвагу превзошла ты",0,553,0,0],["v","И добротою доброту. Просить",0,554,0,0],["v","Тебя не смею я, — не смею также",0,555,0,0],["v","И отговаривать… семью твою",0,556,0,0],["v","Своею смертью ты спасешь, родная.",0,556,0,0],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["dir","с легким оттенком снисходительной иронии"],["v","Благоразумен твой совет — от скверны",0,557,0,0],["v","Уйдешь ты; смертью вольной я умру.",0,558,0,0],["v","Но ты за мною следуй и дыханье",0,559,0,0],["v","Мое последнее прими, покровом",0,560,0,1],["v","Безжизненное тело осеняя.",0,560,0,0],["v","Меча же не боюсь я, коль по праву",0,561,0,0],["v","Геракла дщерью величаюсь я.",0,562,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["dir","сломленный горем"],["v","Нет, не могу твоей я казни видеть…",0,563,0,0],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["dir","презрительно"],["v","Тогда проси, чтоб не в руках мужей,",0,564,0,0],["v","По крайней мере, а в объятьях женских",0,565,0,0],["v","Мне дали жизнь окончить, Иолай!..",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"demofont\">Демофонт</span>"],["v","О девушка несчастная, исполню",0,566,0,0],["v","Твои слова я свято… стыд бы был",0,567,0,0],["v","Твоей не скрасить смерти: так велит мне",0,568,0,0],["v","И наш закон, и рвение твое.",0,569,0,0],["v","Да, самую печальную из всех",0,570,0,1],["v","Я видел долей женских.",0,570,0,0],["sd","(Дает приказ одному из своей свиты; тот уходит. <span class=\"ch\" data-ch=\"makariya\">Макария</span> решительно направляется к нему; он мягко продолжает)"],["v","А теперь",0,571,4,0],["v","Будь ласкова, скажи привет последний",0,572,0,0],["v","И братьям молодым, и старику.",0,573,0,0],["sp","<span class=\"ch\" data-ch=\"makariya\">Макария</span>"],["dir","смягченная"],["v","Прости, старик, прости! И передай",0,574,0,0],["v","Свой ум и этим мальчикам, способный",0,575,0,0],["v","На все дела… умней тебя зачем",0,575,0,0],["v","Им вырастать? И попытайся жизнь им",0,576,0,0],["v","Спасти… да, впрочем, ты и так усерден:",0,577,0,0],["v","Мы все равно что рождены тобой;",0,578,0,0],["v","Мы на твоих руках росли. И я,",0,579,0,0],["v","Цветущая невеста, не колеблюсь",0,580,0,1],["v","За Гераклидов умереть. А вы,",0,580,0,0],["v","Вы, что ко мне теснитесь, дети, братья,",0,581,0,0],["v","Да будет счастье с вами: все дары,",0,582,0,0],["v","Которые в моей таятся жертве,",0,583,0,0],["v","На долю вам пусть выпадут! Старик",0,583,0,0],["v","Вот этот и <span class=\"ch\" data-ch=\"alkmena\">Алкмена</span> там, во храме, —",0,584,0,0],["v","Любите их… Афинян чтите, дети…",0,585,0,0],["v","А если вам бессмертные предел",0,586,0,0],["v","Положат испытаньям и отчизну",0,586,0,0],["v","Когда-нибудь вернут, — не забывайте,",0,587,0,0],["v","Как должно вам спасительницу вашу",0,588,0,0],["v","Могилою почтить. А должно — всех",0,589,0,0],["v","Прекраснее. Сестрою малодушной",0,590,0,1],["v","Я не была у вас — за дом родной",0,590,0,0],["v","Я умерла. Да будет же могила",0,591,0,0],["v","Заменой мне детей не принесенных,",0,592,0,0],["v","Девичества закланного навек…",0,592,0,0],["v","Коль под землею что-нибудь от нас",0,593,0,0],["v","Земное остается… Только лучше,",0,594,0,0],["v","Чтоб не осталось ничего… Куда ж",0,594,0,0],["v","Деваться нам с печалями, коль мертвым",0,595,0,0],["v","Их не дано забыть? А говорят,",0,596,0,0],["v","Что умереть и значит — исцелиться!..",0,596,0,0],["sd","Во время речи <span class=\"ch\" data-ch=\"makariya\">Макарии</span> появляются со стороны города несколько почтенных женщин — жриц Персефоны. Они надевают ей на голову венок, обвязывают ей чело серебряной повязкой; прислужницы снимают с нее накидку пепельного цвета, облачают в белые складчатые ризы и украшают ожерельями и запястьями. Затем старшая жрица, творя тихую молитву, срезает ножом прядь ее волос. Все присутствующие соблюдают благоговейное молчание."],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","О, нет тебя великодушней, нет…",0,597,0,0],["v","И знай, пока ты дышишь и потом",0,598,0,0],["v","Священнее тебя для нас не будет…",0,598,0,0],["v","Прости… прости! Боюсь я оскорбить",0,599,0,0],["v","Печальными словами ту богиню,",0,600,1,1],["v","Которой ты начатки отдала.",0,600,0,0],["sd","Демофонт, <span class=\"ch\" data-ch=\"makariya\">Макария</span> и жрицы удаляются, напутствуемые немыми приветами Гераклидов и хора."],["v","О дети! Ухожу я… горе ломит",0,601,0,0],["v","Состав костей моих… Я упаду…",0,602,0,0],["v","Возьмите, посадите на ступени",0,602,0,0],["v","Алтарные бессильного; ему",0,603,0,0],["v","Вы голову покройте, дети. Тяжким",0,604,0,0],["v","Мне давит сердце бременем ее",0,605,0,0],["v","Погибель. Правда, если бы то слово",0,605,0,0],["v","Вещания презрели мы — нам всем",0,606,0,0],["v","Пришлось бы умереть и чаша горя<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,607,0,0],["v","Полней бы стала, — но полна и эта.",0,607,0,0],["scene","Второй музыкальный антракт","s10",3,10],["sp","Хор"],["str","Строфа"],["v","Нет без божественной воли блаженного мужа,",0,608,0,0],["v","Нет и несчастных…",0,609,1,0],["v","Только не вечно вздымают и боги",0,610,0,1],["v","Тех же людей; судьба нас качает",0,611,1,0],["v","Вверх одного, книзу другого…",0,612,1,0],["v","В бездну она низвергает счастливца,",0,613,0,0],["v","Нищего в выси блаженства возносит.",0,614,0,0],["v","Жребия ты не минуешь, а он над искусством смеется.",0,615,0,0],["v","Труд и борьба — только лишние муки…",0,616,1,0],["str","Антистрофа"],["v","Встань, <span class=\"ch\" data-ch=\"iolay\">Иолай</span>: покоримся божественной воле,",0,617,0,0],["v","Не отдавайся",0,620,1,1],["v","Этим порывам отчаянья, старец;",0,621,0,0],["v","Та, что умрет за братьев и город,",0,622,1,0],["v","Славы свою долю приемлет.",0,623,1,0],["v","Девичье имя в устах не угаснет.",0,624,0,0],["v","Доблести путь пролагает страданье,",0,625,0,0],["v","Дева ж достойной отца и достойною рода явилась…",0,626,0,0],["v","Славить хочу я славные смерти!..",0,627,1,0],["act","Действие третье","a4","III"],["scene","Явление седьмое","s11",4,11],["sd","Со стороны чужбины является слуга Гилла; увидев Гераклидов, радостно подходит к ним."],["sp","Слуга"],["v","О дети, радуйтесь… Где ж <span class=\"ch\" data-ch=\"iolay\">Иолай</span>?",0,630,0,1],["v","И мать отца куда же удалилась?",0,631,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["dir","снимая покров с лица"],["v","Я здесь, коль это точно прежний я.",0,632,0,0],["sp","Слуга"],["v","Но ты лежишь, лицо твое в печали!..",0,633,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Заботою измучен о своих…",0,634,0,0],["sp","Слуга"],["v","Встань, Иолай, и подними лицо!",0,635,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Старик я, и бессилен я, увы!",0,636,0,0],["sp","Слуга"],["v","Но я принес тебе большую радость!",0,637,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Но кто же ты и где встречались мы?",0,638,0,0],["sp","Слуга"],["v","Из Гилловых людей я; не узнал ты?",0,639,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Ты выручить из горя нас идешь?",0,640,0,1],["sp","Слуга"],["v","Да, и теперь идут дела удачней.",0,640,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["dir","поднимается и зовет, обращаясь к храму"],["v","О славного Геракла мать, Алкмена!",0,641,0,0],["v","Приди, услышь счастливейшую весть!",0,642,0,0],["v","Ведь уж давно ты в муках материнских",0,643,0,0],["v","Свое крушила сердце об ушедших,",0,644,0,0],["v","Сужден ли им возврат… Сюда, Алкмена!",0,645,0,0],["scene","Явление восьмое","s12",4,12],["sd","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span> неровною поступью выходит из храма; ее впалые глаза беспокойно блуждают. Увидя <span class=\"ch\" data-ch=\"iolay\">Иолая</span> у алтаря, она вздрагивает и враждебным взором смотрит на слугу."],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Призывы дом наполнили… Скажи,",0,646,0,0],["v","О Иолай, ужель опять микенский",0,647,0,0],["v","Тебя теснит глашатай? Мало сил",0,648,0,0],["v","Оставила нам старость, чужеземец,",0,649,0,0],["v","Но увести детей тебе не дам,",0,650,0,1],["v","Пока еще я матерью Геракла",0,651,0,0],["v","Считаюсь… Только тронь их, и тебе",0,652,0,0],["v","Бесславная борьба грозит — два старца…",0,653,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","О, разуверься, старая, и страх",0,654,0,0],["v","Покинь; врага-глашатая здесь нет…",0,655,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Но ты кричал, нам возвещая ужас…",0,656,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Я вызывал тебя из храма только.",0,657,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","успокоенная"],["v","Я поняла не так… А это кто ж?",0,658,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Он возвестил тебе прибытье внука.",0,659,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Будь счастлив, гость, и ты за эту весть…",0,660,0,1],["v","Но отчего ж, когда он в эту землю",0,660,0,0],["v","Уже пришел, его не видим? Случай",0,661,0,0],["v","Какой ему с тобою помешал",0,662,0,0],["v","Порадовать мне сердце появленьем?",0,663,0,0],["sp","Слуга"],["v","Он войско размещает, что привел.<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,664,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Об этом весть он, верно, шлет не нам.",0,665,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["dir","задетый за живое <span class=\"ch\" data-ch=\"alkmena\">Алкменой</span>"],["v","Пусть не тебе, но все же мне.",0,665,0,0],["sd","(Слуге.)"],["v","Ответствуй!",0,666,4,0],["sp","Слуга"],["v","Что именно хотел бы ты узнать?",0,667,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Союзников привел сюда он много ль?",0,668,0,0],["sp","Слуга"],["v","Я не считал, но знаю — много их.",0,669,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Вожди Афин извещены, конечно?",0,670,0,1],["sp","Слуга"],["v","Нам левое уступлено крыло.",0,671,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","А разве войско там готово к бою?",0,672,0,0],["sp","Слуга"],["v","Уж жертвы ждут, поодаль от рядов.",0,673,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","А далеко ль от них аргосцев копья?",0,674,0,0],["sp","Слуга"],["v","Ты б воеводы различил черты.",0,675,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","А чем же был он занят? Войско строил?",0,676,0,0],["sp","Слуга"],["v","Должно быть, так: нам было не слыхать.",0,677,0,0],["v","Но я пойду. Я не хочу оставить",0,678,0,0],["v","Своих господ, когда вступают в бой.",0,679,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","И я с тобой. У нас забота та же —",0,680,0,1],["v","Друзьям помочь, как требует наш долг.",0,681,0,0],["sp","Слуга"],["dir","недоверчиво глядя на <span class=\"ch\" data-ch=\"iolay\">Иолая</span>"],["v","Не след тебе пустое молвить слово.",0,682,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","А в бранном деле покидать друзей?",0,683,0,1],["sp","Слуга"],["v","Не та, что раньше, сила <span class=\"ch\" data-ch=\"iolay\">Иолая</span>.",0,688,0,1],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Бессилен щит я поразить копьем?",0,685,0,1],["sp","Слуга"],["v","Да, поразишь — и сам падешь на землю.",0,685,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Мой взор один микенцев ужаснет!",0,685,0,0],["sp","Слуга"],["v","Не ранишь взором, коль рука недвижна.",0,684,0,1],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Но ведь числом враги нам не уступят?",0,689,0,1],["sp","Слуга"],["v","Что ж? Перевеса нам и ты не дашь!",0,689,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Не убеждай — решил сражаться я.",0,690,0,0],["sp","Слуга"],["v","Сражаться не тебе — молиться разве.",0,691,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Я не останусь — речь перемени…",0,692,0,0],["sp","Слуга"],["v","Средь латников не воин — безоружный.",0,692,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Вот в этом храме и оружье есть,<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,693,0,0],["v","Что было снято с пленных; нам послужит",0,694,0,0],["v","Теперь оно, и если я живым",0,695,0,0],["v","Вернуся из сражения, сюда же",0,696,0,0],["v","Доставим мы доспехи; но и бог",0,696,0,0],["v","С убитого не взыщет… В эти двери",0,697,0,0],["v","Войди и, сняв с гвоздя, сюда доставь",0,698,0,0],["v","Тяжелые доспехи, да скорее!..",0,699,0,0],["v","Позор тому, кто дом свой охраняет",0,700,0,1],["v","И робко ждет, в брань отпустив друзей!",0,700,0,0],["v","Слуга уходит в храм.",0,701,0,0],["scene","Явление девятое","s13",4,13],["sd","Те же, без слуги. Поселяне с <span class=\"ch\" data-ch=\"alkmena\">Алкменой</span> окружают <span class=\"ch\" data-ch=\"iolay\">Иолая</span>."],["sp","Корифей"],["dir","к <span class=\"ch\" data-ch=\"iolay\">Иолаю</span>"],["v","Не увяло от времени сердце твое,",0,702,0,0],["v","Оно бьется, как раньше, — но сила не та!",0,703,0,0],["v","Не трудись же напрасно во вред самому",0,704,0,0],["v","И без пользы для родины нашей, мой друг;",0,705,0,0],["v","О, опомнись, старик, и несбыточных дум",0,706,0,0],["v","Искушения брось:",0,707,4,0],["v","Не видеть тебе юности дважды!",0,708,2,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","к <span class=\"ch\" data-ch=\"iolay\">Иолаю</span>"],["v","Ты потерял рассудок… Иль меня",0,709,0,0],["v","С детьми одну покинешь? Сам подумай!..",0,710,0,1],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Мужам война — а ты о них заботься!",0,710,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Ну, а тебя убьют… спасемся как?",0,711,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Придумают, коль уцелеют, внуки.",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","А — боже сохрани — на них беда?",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","На доброту друзей тогда надежда…",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","грустно"],["v","Одна и остается — нет другой…",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Да о тебе, жена, и Зевсу думно…",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","опуская глаза"],["v","Увы!",0,716,0,0],["v","Но жалобы из уст моих Кронид,",0,717,0,0],["v","Конечно, не услышит — сам он знает,",0,718,0,0],["v","По правде ли со мной он поступил!..",0,719,0,0],["scene","Явление десятое","s14",4,14],["sd","Из храма возвращается слуга, неся полное вооружение."],["sp","Слуга"],["v","Доспех готов, и полный. Поспеши же",0,720,0,1],["v","Его надеть на тело. Близок бой,",0,720,0,0],["v","И медлящий Аресу ненавистен…",0,721,0,0],["v","Но если вес доспехов испугал",0,722,0,0],["v","Тебя, старик, — их не бери покуда,",0,723,0,0],["v","Иди как есть. На поле битвы ты",0,724,0,0],["v","Наденешь их, я ж донесу до места…",0,725,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Ты прав, возьми покуда наш доспех,",0,726,0,0],["v","Но в руку дай копье мне и, под левый",0,727,0,0],["v","Схвативши локоть, направляй меня.",0,728,0,0],["sp","Слуга"],["dir","насмешливо"],["v","Руководитель воину потребен?",0,729,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Приметы ради — чтоб не оступиться.",0,730,0,1],["sp","Слуга"],["v","Ах, если б с духом мощь твоя сравнялась!",0,731,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Скорей! Позор на битву опоздать!",0,732,0,0],["sp","Слуга"],["dir","с улыбкой"],["v","Да за тобой задержка — не за мной!",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Мои ль не быстры ноги? Погляди…",0,734,0,0],["sp","Слуга"],["v","Гляжу, что ты спешишь, да только в мыслях.",0,735,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Вот грянет битва — и не то ты скажешь.",0,736,0,0],["sp","Слуга"],["v","И что ж скажу? А впрочем — бог нам в помощь.",0,737,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","Что вражий щит пробил я — вот что скажешь.",0,738,0,0],["sp","Слуга"],["v","Коль мы дойдем… Но вот дойдем ли мы?",0,739,0,0],["sp","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>"],["v","О ты, рука моя, такой же верной",0,740,0,1],["v","Союзницей мне будь, какой тебя",0,740,0,0],["v","От юности хранит воспоминанье,",0,741,0,0],["v","Когда с Гераклом Спарту я громил,<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,742,0,0],["v","Тогда мы тыл увидим Еврисфеев:",0,743,0,0],["v","Подобного напора не снести",0,744,0,0],["v","Трусливому. Но вот что худо: всем",0,745,0,0],["v","Мерещится в удаче лживый призрак",0,745,0,0],["v","Отважности, и склонны думать люди,",0,746,0,0],["v","Что раз кто счастлив — все умеет он.",0,747,0,0],["sd","Оба удаляются со сцены. <span class=\"ch\" data-ch=\"alkmena\">Алкмена</span> опускается на ступень алтаря."],["sd","ТРЕТИЙ МУЗЫКАЛЬНЫЙ АНТРАКТ"],["sd","Хор"],["str","Строфа I"],["v","Ты, земля, ты, лампада ночей,",0,748,0,0],["v","Вы, всесветлого бога",0,749,2,0],["v","Нам горящие ярко лучи, —",0,750,0,1],["v","Принесите мне радость",0,751,2,0],["v","И по дальнему небу домчите ее",0,752,0,0],["v","До владычного трона,",0,753,2,0],["v","До дворца синеокой Афины!",0,754,0,0],["v","Да! За отчую землю,",0,755,2,0],["v","За очажное пламя",0,756,2,0],["v","Должен медью сверкать я,",0,757,2,0],["v","Потому что молящие — святы…",0,758,0,0],["str","Антистрофа I"],["v","Хоть тяжело нам считать,",0,759,0,0],["v","Что златые Микены,",0,760,2,1],["v","Осененные славой побед,",0,761,0,0],["v","К нам исполнены злобы —",0,762,2,0],["v","Но стократ тяжелее гостей выдавать,",0,763,0,0],["v","О защите молящих,",0,764,2,0],["v","По приказу царя-лиходея.",0,765,0,0],["v","Зевс за нас; мне не страшно:",0,766,2,0],["v","Зевс за правду воздаст нам",0,767,2,0],["v","Выше божьего слова",0,768,2,0],["v","Не поставлю я смертного волю.",0,769,0,0],["str","Строфа II"],["v","А ты, о дивная! Твои<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,770,0,1],["v","Земля и город, мать Афин,",0,770,0,0],["v","Ты им и страж и властелин,",0,771,0,0],["v","Царя надменного гони!",0,772,0,0],["v","Неправда мощная врагов",0,773,2,0],["v","Рукой преступною ведома —",0,773,2,0],["v","И я ль, боявшийся богов,",0,774,2,0],["v","Лишусь родительского дома?",0,775,2,0],["str","Антистрофа II"],["v","Не твой ли жертвами кишит",0,776,0,0],["v","Приют, Афина? Не тебе ли",0,776,0,0],["v","С тех пор, как город наш стоит,",0,777,0,0],["v","Плясали хоры, девы пели?<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,778,0,0],["v","Тебе звучат их голоса,",0,779,2,0],["v","И танец ноги выбивают,",0,780,2,1],["v","Когда туманом небеса",0,781,2,0],["v","И мраком выси одевают!",0,782,2,0],["act","Действие четвертое","a5","IV"],["scene","Явление одиннадцатое","s15",5,15],["sd","Со стороны чужбины является вестник и подходит к <span class=\"ch\" data-ch=\"alkmena\">Алкмене</span>."],["sp","Вестник"],["v","Я приношу тебе, о госпожа,",0,783,0,0],["v","Известие, для языка и слуха",0,784,0,0],["v","Приятное! Чтоб не тянуть, скажу:",0,785,0,0],["v","С победой мы; из копий и доспехов",0,786,0,0],["v","Твоих врагов уж строится трофей!",0,787,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","О друг, тебе за эту весть отрадной",0,788,0,0],["v","Свободою заплатит день!.. Но нас",0,789,0,0],["v","Не вызволил еще ты совершенно.",0,790,0,1],["v","Боюсь я, живы ль те, кого люблю?",0,791,0,0],["sp","Вестник"],["v","Они живут и славой увенчались.",0,792,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Но <span class=\"ch\" data-ch=\"iolay\">Иолай</span>, старик… Он тоже жив?",0,793,0,0],["sp","Вестник"],["v","Особо он почтен богами даже…",0,794,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","В сраженье отличился он? Иль как?",0,795,0,0],["sp","Вестник"],["v","Бессмертные ему вернули юность.",0,796,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Чудесна речь твоя… Но передай",0,797,0,0],["v","Мне первым делом ход борьбы счастливой.",0,798,0,0],["sp","Вестник"],["v","Все объяснит тебе один рассказ.",0,799,0,0],["v","Когда ряды гоплитов развернулись",0,800,0,1],["v","Лицом к лицу, то с колесницы Гилл",0,800,0,0],["v","Спускается и, став на вольном месте",0,801,0,0],["v","Меж двух дружин, так говорит: \"О вождь,",0,802,0,0],["v","Из Аргоса пришедший! Отчего бы",0,803,0,0],["v","Не пощадить нам эту землю? Зла",0,804,0,0],["v","Большого и Микены не потерпят,",0,805,0,0],["v","Коль одного лишатся мужа. Мы",0,805,0,0],["v","На поединок выйдем; если боги",0,806,0,0],["v","Дадут тебе убить меня, — детей",0,807,0,0],["v","Геракловых ты уведешь; а если",0,808,0,0],["v","Тебя убью, — пусть не мешают нам",0,809,0,0],["v","Забрать и власть, и дом отца, аргосец…\"",0,810,0,1],["v","И кликами венчали те слова",0,810,0,0],["v","Ряды солдат: конец им полюбился",0,811,0,0],["v","Страданья боевого — и отвага.",0,812,0,0],["v","Но <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span>, людей не устыдясь,",0,813,0,0],["v","Что Гераклида слышали, и трусость",0,814,0,0],["v","Позорно выставляя, — воевода! —",0,815,0,0],["v","На смелый вызов витязя смолчал.",0,816,0,0],["v","И слабые такие помышляют",0,817,0,0],["v","Геракловых детей поработить!..",0,818,0,0],["v","Вернулся Гилл в ряды; тогда пророки,",0,819,1,0],["v","Поняв, что брань закончить поединком",0,820,0,1],["v","Не суждено, без промедленья жертвы",0,820,0,0],["v","Ножом заклали. Падают — и кровь,",0,821,0,0],["v","Потоками из раны хлынув, милость",0,822,0,0],["v","Бессмертных возвещает. Колесниц",0,822,0,0],["v","Ряды тогда наполнились, а тесно",0,823,0,0],["v","Сплотившихся тяжелые щиты",0,824,0,0],["v","Покрыли… Вождь афинский ободрял",0,824,0,0],["v","Своих бойцов по-царски: \"О мои",0,825,0,0],["v","Сограждане! Земле, что вас родила,",0,826,0,0],["v","Что вас любовно кормит, — ей теперь",0,826,0,0],["v","Вы послужить должны!\" А неприятель",0,827,0,0],["v","Тем временем соратников молил,",0,828,0,0],["v","Чтобы Микен они не посрамили",0,828,0,0],["v","И Аргоса. Но яркая труба",0,829,0,0],["v","Тирренская призывом зазвучала,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,830,0,1],["v","И ты представь себе, какие вслед",0,830,0,0],["v","Удары щит о щит, и крик, и стоны",0,831,0,0],["v","Подъялись вихрем тяжким… И напор",0,832,0,0],["v","Копейщиков аргосских очень скоро",0,833,0,0],["v","Прорвал ряды афинские… потом",0,834,0,0],["v","Враг отступил… но грудь на грудь вторично",0,835,0,0],["v","Сошлися мы с аргосцами… И бой",0,836,0,0],["v","Упорный загорелся. И убитых",0,837,0,0],["v","Тут полегло немало. Два кругом",0,838,0,0],["v","Носилося призыва в поле: «Аргос», —",0,839,0,0],["v","«Афиняне», — \"не посрамите стен",0,840,0,1],["v","Отеческих!\". С усильем, но микенцев",0,840,0,0],["v","Мы все-таки прогнали.",0,841,0,0],["v","<span class=\"ch\" data-ch=\"iolay\">Иолай</span>",1,841,0,0],["v","Тогда старик является; десницу",0,842,0,0],["v","С мольбою простирая к Гиллу, он",0,843,0,0],["v","Себе на колеснице места просит;",0,844,0,0],["v","И, вожжи взяв, за <span class=\"ch\" data-ch=\"evrisfey\">Еврисфеем</span> вслед",0,845,0,0],["v","Возница устремился.",0,845,0,0],["v","Дальше я",1,845,0,0],["v","Со слов чужих могу поведать только",0,846,0,0],["v","Движение событий. Проезжая<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,847,0,0],["v","Мимо холма Палленского, что был<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,848,0,0],["v","Афине посвящен, завидел старец",0,849,0,0],["v","Аргосского царя… тогда мольбы",0,850,0,1],["v","Он жаркие вознес к отцу бессмертных",0,850,0,0],["v","И Гебе, чтоб ему на день один",0,851,0,0],["v","Они вернули молодость и дали",0,851,0,0],["v","Врагам отмстить… И тут готовься весть",0,852,0,0],["v","О чуде услыхать, царица. Только",0,853,0,0],["v","Окончил он молитву, — две звезды",0,853,0,0],["v","Поверх ярма сверкнули, колесницу ж",0,854,0,0],["v","Одела ночи мгла. Нам мудрецы",0,855,0,0],["v","Так объяснили, что то были — Геба",0,855,0,0],["v","И твой, царица, сын. И вот внезапно<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,856,0,0],["v","Рассеялся туман густой, и мы",0,856,0,0],["v","Увидели того же <span class=\"ch\" data-ch=\"iolay\">Иолая</span>,",0,857,0,0],["v","Но только молодым героем, силы",0,858,0,0],["v","Исполненным нетронутой. И горд",0,858,0,0],["v","И смел, на <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span> прянув возле",0,859,0,0],["v","Скиронских скал, он в плен его берет",0,860,0,1],["v","И, оковав, тебе ведет — трофей",0,860,0,0],["v","Блистательный — счастливого дотоле",0,861,0,0],["v","Властителя. Какой урок для нас,",0,862,0,0],["v","Чтоб зависти мы не питали к жизни,",0,863,0,0],["v","Счастливой с виду, до конца ее:",0,864,0,0],["v","Так скоротечны дни благополучья!",0,865,0,0],["sp","Корифей"],["v","О Зевс, о бог-защитник! День, свободный",0,866,0,0],["v","От ужасов, ты нам явил теперь!",0,867,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","О Зевс! Ты поздно взор свой обратил",0,868,0,0],["v","На бедствия <span class=\"ch\" data-ch=\"alkmena\">Алкмены</span>; но тебя",0,869,0,0],["v","Благодарю я все ж за милость. Знаю,",0,870,0,1],["v","Что сын мой средь богов — да, ныне знаю;",0,870,0,0],["v","А раньше мне не верилось. И вы,",0,871,0,0],["v","О дети, вы свободны от страданий:",0,872,0,0],["v","Бояться вам не надо <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span>!",0,873,0,0],["v","Погибнет он постыдно, вы ж опять",0,873,0,0],["v","Удел отца увидите, богам",0,874,0,0],["v","Отечества вы принесете жертвы",0,875,0,0],["v","Не на чужой земле, а на родной,",0,876,0,0],["v","С которой вас прогнали, осудив",0,876,0,0],["v","Скитаться средь несчастий и лишений.",0,877,0,0],["v","Но объясни, понять я не могу,",0,878,1,0],["v","Какой расчет заставил <span class=\"ch\" data-ch=\"iolay\">Иолая</span>",0,879,0,0],["v","Аргосского владыку пощадить?",0,880,0,1],["v","По-моему, живым врага оставить,",0,881,0,0],["v","Коль он у нас в руках, — одно безумье.",0,882,0,0],["sp","Вестник"],["v","Хотел тебе доставить радость он,",0,883,0,0],["v","Чтоб ты врагом плененным насладилась.",0,884,0,0],["v","Противился микенец, не хотел",0,885,0,0],["v","Ярма надеть и на глаза твои",0,886,0,0],["v","Живым предстать за полученьем кары.",0,887,0,0],["v","О старая жена, возвеселись,",0,888,0,0],["v","Да не забудь, что первые слова",0,889,0,0],["v","Прервала ты, свободу обещав мне…",0,890,0,1],["v","В таких делах уста царей не лгут!..",0,890,0,0],["scene","Четвертый музыкальный антракт","s16",5,16],["sp","Хор"],["str","Строфа I"],["v","Сладок нам танец и пир,",0,891,0,0],["v","Прелестью флейт полный;",0,892,0,0],["v","Чары Киприды нам",0,893,0,0],["v","Негою сердце тешат;",0,894,0,0],["v","Мило и счастье друзей,",0,895,0,0],["v","Если придет нежданно…",0,896,0,0],["v","Сколько у Мойры в руках",0,897,0,0],["v","Пряжи, и сколько с нею",0,898,0,0],["v","Времени сын Век",0,899,0,0],["v","Нитей мотает…",0,900,0,1],["str","Антистрофа I"],["v","Избран, о город, тобой",0,900,0,0],["v","Праведный путь: вы бессмертных",0,901,0,0],["v","Чтите, Афины, — так",0,902,0,0],["v","Вечно творите. Ярок",0,903,0,0],["v","Гибели вражьей пример.",0,904,0,0],["v","Правду хотел безумец",0,905,0,0],["v","Поколебать, и его",0,906,0,0],["v","Боги казнили. Гордость",0,907,0,0],["v","Мысли всегда бог",0,908,0,0],["v","Смутой наполнит…",0,909,0,0],["str","Строфа II"],["v","На небесах твой славный сын,",0,910,0,1],["v","Царица старая; не прав,",0,910,0,0],["v","Кто молвит, что в Аиде он,",0,911,0,0],["v","Оставив пепел на костре.",0,912,0,0],["v","Там в золотом чертоге",0,913,0,0],["v","Гебы дивное ложе",0,914,2,0],["v","Делит он… О Гименей,",0,915,2,0],["v","Браком связал ты славным",0,916,2,0],["v","Зевсово чадо с чадом",0,917,2,0],["v","Зевса навеки.",0,918,2,0],["str","Антистрофа II"],["v","Как часто звеньями в цепи",0,919,0,0],["v","Дела становятся! Отец",0,920,0,1],["v","Малюток этих был спасен",0,920,0,0],["v","Афиной, — город наш детей,",0,921,0,0],["v","Славный народ Паллады,",0,922,2,0],["v","Спас, надменность карая",0,923,2,0],["v","Мужа, который закон",0,924,2,0],["v","Буйно нарушил. Сердцу",0,925,2,0],["v","Ярые страсти, гордость —",0,926,2,0],["v","Будьте вы чужды…",0,927,2,0],["act","Исход","a6",""],["scene","Явление двенадцатое","s17",6,17],["sd","Приходят слуги, ведущие с собою пленного <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span>."],["sp","Слуга"],["v","О госпожа, хоть видишь ты, но все же",0,928,0,0],["v","И я скажу: вот <span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span> — тебе",0,929,0,0],["v","Нежданный дар; судьбы такой, конечно,",0,930,0,1],["v","Не ждал и он, особенно когда",0,930,0,0],["v","Он, бранные Микены покидая,",0,931,0,0],["v","Вел рать свою надменно и мечтал",0,932,0,0],["v","Афинские разрушить стены… разве",0,933,0,0],["v","Он чаял быть в твоих руках? Но бог",0,933,0,0],["v","Обратное его предначертаньям",0,934,0,0],["v","Решил и дал событьям ход иной:",0,935,0,0],["v","Царь Гилл, а с ним и <span class=\"ch\" data-ch=\"iolay\">Иолай</span> почтенный",0,936,0,0],["v","Крониду в честь победы приношенье",0,936,0,0],["v","Готовят там и поручили мне",0,937,0,0],["v","Отрадный дар доставить этот. Слаще",0,938,0,0],["v","Для сердца нет, коль видишь ты врага,",0,939,0,0],["v","Счастливого так долго, в униженье!",0,940,0,1],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","с сверкающими глазами подходит к <span class=\"ch\" data-ch=\"evrisfey\">Еврисфею</span>"],["v","Так вот ты, ненавистный! Наконец",0,941,0,0],["v","И до тебя добралась Правда! Ну-ка,",0,942,0,0],["v","Гляди сюда, осмелься на врагов",0,943,0,0],["v","Глаза поднять… Ты слушаться нас должен,",0,944,0,0],["v","Не мы тебя!.. Неужто это ты",0,945,0,0],["v","Действительно тот самый, что Геракла —",0,946,0,0],["v","Того Геракла, сына моего,",0,947,0,0],["v","Который средь богов теперь, — измучил?",0,948,0,0],["v","Живым его в юдоль Аида даже",0,949,0,0],["v","Сойти принудил, гидр и львов его",0,950,0,1],["v","Губить себе в угоду заставлял?",0,950,0,0],["v","Не говорю о хитростях иных,",0,951,0,0],["v","Придуманных твоею злобой; был бы",0,952,0,0],["v","Их список слишком длинен… Но тебе",0,952,0,0],["v","И этого казалось мало, дерзкий:",0,953,0,0],["v","Детей и нас по всей Элладе ты",0,954,0,0],["v","От алтаря до алтаря скитаться,",0,954,0,0],["v","И стариков и малых, осудил…",0,955,0,0],["v","Вот наконец нашелся город, люди,",0,956,0,0],["v","Которые свободу любят; ты",0,956,0,0],["v","Их запугать не мог — и злую смерть",0,957,0,0],["v","Ты обретешь. Ты выгадал и тут…",0,958,0,0],["v","За бедствия, которые тобою",0,958,0,0],["v","Принесены нам были, не одной,",0,959,0,0],["v","А тысячи тебе бы казней мало!",0,960,0,1],["sp","Слуга"],["v","Но все ж его не вправе ты казнить.",0,960,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Тогда напрасно в плен его мы брали;",0,961,0,0],["v","Но где ж закон, спасающий его?",0,962,0,0],["sp","Слуга"],["v","Афинские владыки так решили.",0,963,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Что это? Смерти предавать врага —",0,964,0,0],["v","По мнению афинян, не прекрасно?",0,965,0,0],["sp","Слуга"],["v","Нет, если взят живым он на войне.",0,966,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","А Гилл? Решенье он признал такое?",0,967,0,0],["sp","Слуга"],["v","Что ж, быть ему ослушником Афин?",0,968,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Что ж, быть живым и здравым <span class=\"ch\" data-ch=\"evrisfey\">Еврисфею</span>?",0,969,0,0],["sp","Слуга"],["v","Тогда неправдой был и плен его.",0,970,0,1],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Еще не поздно ту неправду сгладить!",0,971,0,0],["sp","Слуга"],["dir","настойчиво"],["v","Нет здесь того, кто б мог его убить!",0,972,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","гневно"],["v","Здесь я! А я ведь — тоже некто, мнится.",0,973,0,0],["sp","Слуга"],["v","Смотри! Бесславьем ты себя покроешь.",0,974,0,0],["sd","(Уходит с угрожающим жестом.)"],["scene","Явление тринадцатое","s18",6,18],["sd","Те же, без слуги."],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Люблю Афины я, люблю бесспорно;",0,975,0,0],["v","Но <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span> — раз он мне достался —",0,976,0,0],["v","Не властен вырвать из людей никто.",0,977,0,0],["v","Кто хочет, пусть меня и дерзкой кличет,",0,978,0,0],["v","И преступившей женских чувств предел,",0,979,0,0],["v","А месть свою я утолю всемерно.",0,980,0,1],["sp","Корифей"],["v","Питаешь гнев ужасный ты, жена,",0,980,0,0],["v","На <span class=\"ch\" data-ch=\"evrisfey\">Еврисфея</span>; знаю — и прощаю.",0,981,0,0],["sd","Тем временем <span class=\"ch\" data-ch=\"alkmena\">Алкмена</span> опять подошла к <span class=\"ch\" data-ch=\"evrisfey\">Еврисфею</span>; тот смотрит на нее в упор."],["sp","<span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span>"],["v","Не мни, жена, что в жизнелюбья страсти",0,982,0,0],["v","До льстивых слов унижу я себя;",0,983,0,0],["v","Нет, трусостью уже не согрешу я.",0,984,0,0],["v","Вражду на сына твоего воздвиг",0,985,0,0],["v","Я не по доброй воле; был я братом",0,986,0,0],["v","Двоюродным тебе, и общность крови",0,987,0,0],["v","Меня с твоим Гераклом единила.",0,988,0,0],["v","Но все равно, хотел иль не хотел я —",0,989,0,0],["v","Внушила Гера эту мне болезнь,",0,990,0,1],["v","Она ж была богинею. И вот я",0,990,0,0],["v","Врагом себя Гераклу объявил.",0,991,0,0],["v","А раз вступив на путь вражды жестокой,",0,992,0,0],["v","Я много мук ему изобретал",0,993,0,0],["v","И, Ночь советчицей избрав, немало",0,994,0,0],["v","Ткал замыслов, чтоб, свергнув супостата,",0,995,0,0],["v","Остаток дней безоблачно провесть.",0,995,0,0],["v","Ведь достоверно знал я, что твой сын —",0,996,0,0],["v","Муж настоящий, не пустое имя:",0,997,0,0],["v","Ты видишь, хоть и враг он мне — за доблесть",0,998,0,0],["v","Я на хвалу ему не поскуплюсь.",0,999,0,0],["v","И вот он умер; что ж? Не знал я разве",0,1000,0,1],["v","Про ненависть ко мне его детей",0,1000,0,0],["v","И про вражды наследственность? И диво ль,",0,1001,0,0],["v","Что все пути я испытал, стараясь",0,1002,0,0],["v","Убить их иль изгнать? Иль средство было",0,1002,0,0],["v","Иное у меня, чтоб мне свое",0,1003,0,0],["v","Обезопасить царство? Ты сама бы, —",0,1004,0,0],["v","Когда бы жребии сменились наши, —",0,1005,0,0],["v","Детенышей разгневанного льва",0,1005,0,0],["v","Ужели злых терпеть бы стала, жить",0,1006,0,0],["v","Им в Аргосе дала б на воле? В этом",0,1007,0,0],["v","Ты никого не убедишь, жена!",0,1007,0,0],["v","Теперь — свершилось! Смерти жаждал я —",0,1008,1,0],["v","Меня живым оставили. Отныне —",0,1009,0,0],["v","Так верует Эллада вся — никто",0,1010,0,1],["v","Меня без скверны уж убить не может.",0,1010,0,0],["v","Афины благочестье соблюли:",0,1011,0,0],["v","Не ставя гнева выше божьей воли,",0,1012,0,0],["v","Меня велели отпустить они.",0,1013,0,0],["v","Сказала ты — сказал и я. В дальнейшем",0,1014,1,0],["v","Уж нет врагов, а есть проситель скромный",0,1015,0,0],["v","И покровитель благородный. Впрочем,",0,1015,0,0],["v","Мне все равно: хоть смерти не желаю —",0,1016,0,0],["v","Без горечи расстанусь с жизнью я!",0,1017,0,0],["sp","Корифей"],["v","Внемли совету кроткому, <span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>:",0,1018,0,0],["v","Почти наш город — мужа отпусти!",0,1019,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","озаренная новой мыслью, с жестокой улыбкою"],["v","А коль убью его без ослушанья?",0,1020,0,1],["sp","Корифей"],["v","То было б лучшим; как же совместишь?",0,1020,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["v","Сейчас поймешь. Его лишу я жизни,",0,1021,0,0],["v","А труп отдам родным, когда придут.",0,1022,0,0],["v","Так в отношенье тела волю граждан",0,1022,0,0],["v","Исполню свято, он же понесет",0,1023,0,0],["v","Из рук моих заслуженную кару.",0,1024,0,0],["sp","<span class=\"ch\" data-ch=\"evrisfey\">Еврисфей</span>"],["v","Что ж, убивай… вымаливать себе",0,1025,0,0],["v","Спасения не буду. Град же этот",0,1025,0,0],["v","За то, что отпустил меня и верность",0,1026,0,0],["v","Просителю соблюл, получит дар",0,1027,0,0],["v","Великий от меня — вещанье Феба.",0,1027,0,0],["v","В цене высокой он с годами будет,",0,1028,0,0],["v","Не вздумать даже вам теперь. Меня",0,1029,0,0],["v","Похоронить прошу, где мне судьбою",0,1030,0,1],["v","Назначено, у храма Девы бранной",0,1030,0,0],["v","Палленского! Землей засыпан, гость",0,1031,0,0],["v","Афинского предела, я останусь",0,1032,0,0],["v","Хранителем для вас и другом верным,",0,1032,0,0],["v","А для потомства этих Гераклидов",0,1033,0,0],["v","Врагом непримиримым, коль придут",0,1034,0,0],["v","С дружиною бесчисленной в Афины,",0,1035,0,0],["v","Забыв о вашей ласке. Вот кого",0,1035,0,0],["v","Пригрели вы! Вы спросите, как мог я,",0,1036,0,0],["v","Оракулом владея тем, бесстрашно",0,1037,0,0],["v","Идти сюда? Увы! Я Геру мнил",0,1037,0,0],["v","Сильнее всех вещаний; не считал я,",0,1038,0,0],["v","Что нас она покинет! На моем",0,1039,0,0],["v","Не надо гробе крови, возлияний;",0,1040,0,1],["v","Довольно с нас и нашей мести, — я,",0,1041,0,0],["v","Несчастный, дам возврат им, а Афинам",0,1042,0,0],["v","Двойною пользой будет смерть моя:",0,1043,0,0],["v","Я им заступник — и врагам их враг!",0,1044,0,0],["sp","<span class=\"ch\" data-ch=\"alkmena\">Алкмена</span>"],["dir","к поселянам, с сарказмом"],["v","Чего ж вам медлить? Смерть его отраду",0,1045,0,0],["v","И вам сулит, и вашим детям; сами",0,1046,0,0],["v","Вы слышали — убейте же его.",0,1047,0,0],["v","Он сам вам путь надежный указует:",0,1048,0,0],["v","При жизни враг он всем, по смерти — друг.",0,1049,0,0],["v","Итак, ведите, слуги, вы его,",0,1050,0,0],["v","А после казни труп похороните.",0,1051,0,0],["sd","(<span class=\"ch\" data-ch=\"evrisfey\">Еврисфею</span>.)"],["v","Того не будет, чтоб меня вторично,",0,1052,0,0],["v","Живой, изгнал ты из земли моей!",0,1053,0,0],["sd","(Уходит.)"],["sp","Корифей"],["v","Мы согласны. Рабы, уведите его!",0,1054,0,0],["v","И не будет от нас",0,1055,3,0],["v","Государям страны оскверненья!",0,1056,0,0],["v","Хор покидает орхестру.",0,1057,0,0],["h1","Комментарий","comm"],["p","Хотя о времени постановки трагедии не сохранилось документальных данных, оно определяется достаточно точно из сопоставления ее текста с фактами Пелопоннесской войны. В своем пророчестве Еврисфей обещает жителям аттического Четырехградья (см. ниже), что он и после смерти будет защищать их от вражеского нашествия (ст. 1030-1037); эти слова имели смысл только весной 430 г., ибо во время первого вторжения летом 431 г. спартанцы действительно воздержались от разорения Четырехградья в память о своих предках Гераклидах, а уже летом 430 г. опустошили всю Аттику без разбора (Фукидид, II, 55-57). Затем, в финале трагедии очевидно противопоставление афинян, гуманных в своем отношении к пленникам, жестоким спартанцам, и это противопоставление прозвучало бы лицемерно, после того как осенью 430 г. афиняне убили захваченных ими у фракийского царя Ситалка спартанских послов. Следовательно, единственной возможной датой для постановки «Гераклидов» остается весна 430 г."],["p","В основу сюжета трагедии положено сказание о бедственных скитаниях детей Геракла после его смерти, известное в Древней Греции в нескольких вариантах. По наиболее древнему из них, толпу Гераклидов, преследуемых извечным врагом их отца Еврисфеем, возглавлял старинный соратник Геракла, фиванский герой Иолай, который в день боя обрел от богов свою юношескую силу (ср. ст. 796,851-858) и недалеко от Фив сразил Еврисфея в решающей схватке. По другому варианту, Гераклиды безуспешно искали спасения от Еврисфея в различных греческих государствах, в том числе у трахинского царя Кеика (ст. 193), пока не пришли в так называемое аттическое Четырехградье — местность, расположенную на северо-востоке от Афин и объединяющую поселения Марафон, Эною, Трикориф и Пробалинф."],["p","Здесь Гераклиды нашли защиту у афинян, которые еще в V в. гордились тем, что они единственные из всех греков приютили детей Геракла и дали отпор Еврисфею. Соответственно, и место сражения переносилось в Аттику, а бежавший Еврисфей находил свою смерть от руки Иолая уже у Скироновых скал, на границе Мегариды и Коринфа, где Иолай настигал его (ст. 859-863). Еврипид выбрал именно этот, аттическо-марафонский вариант, изменив только его конец (см. ст. 961 и сл.). Хотя аттическая версия мифа являлась достаточно старинной, неизвестно, имел ли Еврипид предшественников в ее обработке для афинского театра: сюжет не дошедшей трагедии «Гераклиды» Эсхила составляла, по мнению ряда исследователей, смерть Геракла, т. е. тема, обработанная в «Трахинянках» Софокла."],["p","В течение последних десятилетий «Гераклидам» Еврипида давалась самая противоречивая оценка; в частности, усиленно дебатировался вопрос, дошло ли до нас его подлинное произведение или позднейшая переделка. Одним из основных аргументов ученых, считающих сохранившийся текст искаженным, служит отсутствие рассказа о жертвоприношении Макарии, который должен был бы напоминать монолог Талфибия в «Гекубе» (ст. 518-582). Единственный намек на это событие в ст. 821 сл. (в переводе Анненского — Зелинского этот намек сознательно опущен) считают недостаточным для завершения сюжетной линии, имеющей столь существенное значение в ходе действия всей трагедии. К тому же у поздних античных авторов встречается несколько цитат из «Гераклидов», не находящих соответствия в нашем тексте трагедии, — создается впечатление, что они заимствованы из оригинала, в то время как до нас дошла более поздняя переработка для нужд эллинистической сцены. Наконец, необычная для Еврипида краткость трагедии (1055 стихов в «Гераклидах» против 1419 в написанной за год до этого «Медее» и 1466 — в «Ипполите») тоже как будто бы наводит на мысль о сокращенном варианте. В последнее время, однако, против приведенных выше аргументов выдвигаются контрдоводы, и хотя вопрос нельзя считать окончательно решенным, следует, во всяком случае, воздержаться от гипотетического восстановления утерянных, возможно, частей прежнего текста."],["p","Перевод пьесы сохранился только в переработке Ф. Ф. Зелинского; ст. 494497, 970-1002 и 1049-1055 переведены им самим, ремарки тоже принадлежат ему (поэтому мы позволили себе их местами немного сократить). Зелинский цитирует в своих примечаниях некоторые отвергнутые им строки Анненского; мы по возможности вставляем их в основной текст."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"]],"n":{"k1":["Ст. 2. Что праведный…","Анненский переводил в другом понимании: «Что ближние для справедливых только / Одних и существуют…»"],"k2":["Ст. 35. Наследье Пандиона.","См. примеч. к «Медее», ст. 665. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 665. Пандион.</b> легендарный афинский царь, отец Эгея.</span><!--/xn-->"],"k3":["Ст. 36. В них кровь одна с Геракловым потомством…","Еврипид следует здесь тому варианту мифологической генеалогии, по которому Алкмена, мать Геракла, и Эфра, мать Тесея, являлись обе внучками Пелопа. В свою очередь, Алкмена и Еврисфей являются двоюродными братом и сестрой, так как их отцы — сыновья Персея, а матери — дочери Пелопа (см. также ст. 207-212, 987 и сл.)."],"k4":["Ст. 49. Глашатай Еврисфея.","В тексте трагедии имя глашатая Еврисфея нигде не названо, однако оно хорошо известно из «Илиады», XV, 638-641."],"k5":["Ст. 60","…град каменьев… — В Аргосе Иолая и Гераклидов ждет избиение камнями, древний вид казни. Ср.: «Илиада», III, 56 сл.: «…давно б уже был ты каменной ризой одет…»"],"k6":["Ст. 80. Четырехградье","название Марафонской области к северо-востоку от Афин."],"k7":["Ст. 110","После этих слов в рукописи пропущено высказывание Копрея, по смыслу восполненное Ф. Ф. Зелинским."],"k8":["Ст. 131","Он поступил как варвар. — Возможно, реминисценция из «Просительниц» Эсхила, где посол Египтиадов так же нагло пытается оторвать от алтаря Данаид."],"k9":["Ст. 176-178","…предпочитая слабых… — Традиционная оценка внешней политики афинян, гордившихся своей ролью защитников угнетенных во всей Греции. Ср. в речи Перикла у Фукидида, II, 40, 4-5: «В отношениях человека к человеку мы поступаем противоположно большинству: друзей мы приобретаем не тем, что получаем от них услуги, но тем, что сами их оказываем… Мы одни оказываем благодеяния безбоязненно, не столько из расчета на выгоды, сколько из доверия, покоящегося на свободе»."],"k10":["Ст. 179-180. Не выслушав обоих…","Также идеализированная характеристика афинской демократии, предоставляющей каждому право высказать свое мнение. Ср. у Фукидида, II, 40, 2: «Мы сами обсуждаем наши действия или стараемся правильно оценить их, не считая речей чем-то вредным для дела; больше вреда, по нашему мнению, происходит, если приступать к исполнению необходимого дела без предварительного уяснения его речами»."],"k11":["Ст. 270 сл","..придется плакать… — Еврипид смягчает старинную версию мифа, согласно которой Копрей был убит афинянами при попытке увести Гераклидов (ср. ст. 294-296)."],"k12":["Ст. 280","В угрозе Копрея проецируется в легендарное прошлое военно-политическая ситуация в Афинах весной 430 г."],"k13":["Ст. 310-315","Иолай призывает Гераклидов в случае их возвращения в родную страну хранить вечную дружбу с афинянами, чего их потомки — спартанцы — как раз не делают."],"k14":["Ст. 316. Пеласги","так греки называли древнейших обитателей Арголиды; ср. «Просительниц» Эсхила, где сам царь Аргоса носит имя Пеласга."],"k15":["Ст. 327","и сл. Частое в трагедиях Еврипида рассуждение о том, что у хороших родителей редко вырастают достойные их дети."],"k16":["Ст. 474","Хотя имя Макарии в тексте трагедии нигде не упоминается, оно является общепринятым; это имя носил источник на Марафонской равнине, название которого связывали с местом, где была принесена в жертву дочь Геракла."],"k17":["Ст. 607","После этого стиха филологи начала XX в. (в том числе Зелинский) предполагали большой кусок утраченного текста — возможно, песнь хора к элевсинским богиням, потом рассказ вестника (или Демофонта) о смерти Макарии и плач по Макарии. У позднеантичных авторов сохранились цитаты из «Гераклидов», отсутствующие в известном нам тексте; они могут относиться к этой выпавшей сцене. Ф. Ф. Зелинский перевел их в своих примечаниях; первый из них может быть пересказом предсмертных жалоб Макарии, два других — сентенциозного содержания: 1) Ах, быть закланной — страшно, хоть и славно; Уйти от смерти — трусость, но и сладость. 2) Ведь кто при жизни чтит его родивших, Тот и живой и мертвый мил богам. А кто отцу отказывает в чести, Тот да не будет ни в молитве мне Сообщником, ни спутником на судне. 3) Три доблести превыше всех, мой сын, Ценить ты должен: чтить богов бессмертных — Родителям почтенье воздавать — И соблюдать закон Эллады общий. Так поступай — и ты венец стяжаешь Неразрушимой славы навсегда."],"k18":["Ст. 664. Он войско размещает…","Здесь некоторое противоречие со ст. 45, где отсутствие Гилла объяснялось тем, что он отправился на поиски нового убежища для Гераклидов, если им не удастся заручиться помощью афинян. Греческих трагиков и зрителей такая непоследовательность не тревожила: всегда можно было предположить, что Гилл, получив известие о поддержке со стороны Демофонта, сумел обеспечить себе новых союзников."],"k19":["Ст. 695. …в этом храме и оружье есть…","Доспехи с взятых в плен или убитых врагов посвящались обычно богу и хранились в его храме."],"k20":["Ст. 743. …с Гераклом Спарту я громил.","Иолай вспоминает поход Геракла против спартанского царя Гиппокоонта, незаконно лишившего престола своего брата Тиндарея; с помощью Геракла Гиппокоонт был свергнут, и Тиндарей возвратил себе царский трон. Из всех подвигов Геракла, в которых принимал участие Иолай, Еврипид вспоминает именно поход на Спарту, что вполне естественно в условиях начавшейся Пелопоннесской войны."],"k21":["Ст. 770-783. А ты, о дивная!","обращение к Афине, покровительнице аттической земли."],"k22":["Ст. 777. …плясали хоры, девы пели…","Имеется в виду праздник Великих Панафиней, в состав которого входили ночные жертвоприношения, сопровождаемые культовыми хорами и плясками афинских юношей и девушек."],"k23":["Ст. 830. Тирренская труба.","Изготовлявшиеся из меди боевые трубы считались изобретением этрусков, известных грекам под именем тирренцев."],"k24":["Ст. 847-848. …со слов чужих могу поведать только движение событий.","Скептическое отношение Еврипида к чудесному омоложению Иолая."],"k25":["Ст. 848. Паллены","дем в Аттике, примерно в 12 км восточнее Афин; на холме находилось святилище богини Афины (см. ст. 1030 и сл.)."],"k26":["Ст. 854-855. …Геба и твой, царица, сын.","Согласно мифу, известному уже из «Одиссеи» (XI, 601 — 604), Геракл был после смерти перенесен на Олимп и ему отдали в жены дочь Зевса, богиню Гебу, олицетворяющую вечную юность. Этим объясняется ее участие и в возвращении молодости Иолаю (ср. ст. 871, 910-918)."]},"mainEnd":1579,"c":[{"id":"iolay","name":"Иолай","role":"Племянник и соратник Геракла","intro":"Старик, защищающий детей умершего Геракла от Еврисфея.","arc":"Иолай — дряхлый старик, который водит Гераклидов из города в город, нигде не находя защиты. Жалкий в начале, он в решающий миг требует оружия, вызывая насмешки слуги, — и, по рассказу вестника, чудесно молодеет в бою и сам берёт в плен Еврисфея.","st":[{"i":110,"p":7,"l":"Пролог · явление второе","t":"У алтаря","d":"Глашатай Еврисфея Копрей отталкивает его от алтаря Зевса в Марафоне; старик падает и зовёт на помощь.","c":"Защитник беззащитен — нужен новый покровитель.","k":false},{"i":540,"p":34,"l":"Действие первое · явление четвертое","t":"Покровительство Афин","d":"Демофонт отказывает глашатаю; Иолай благословляет Афины.","c":"Надежда найдена.","k":false},{"i":900,"p":57,"l":"Действие второе · явление шестое","t":"Жертва девушки","d":"Узнав, что оракул требует принести в жертву знатную деву, готов умереть сам; но Макария вызывается вместо него.","c":"","k":false},{"i":1190,"p":75,"l":"Действие третье · явление десятое","t":"Старик вооружается","d":"Несмотря на насмешки слуги и Алкмены, надевает доспех и идёт в бой.","c":"Мужество вопреки возрасту.","k":true},{"i":1337,"p":85,"l":"Действие четвертое · явление одиннадцатое","t":"Помолодевший","d":"Вестник рассказывает, что Иолай, по молитве к Гебе и Зевсу, вновь стал юношей и пленил Еврисфея.","c":"","k":false}],"gen":"Иолай"},{"id":"demofont","name":"Демофонт","role":"Царь Афин, сын Тесея","intro":"Афинский царь, принимающий молящих под защиту.","arc":"Демофонт воплощает образ идеальных Афин — защитницы гонимых. Но и ему ставят предел: оракул требует человеческой жертвы, и он, не желая губить своих граждан, оказывается в тупике.","st":[{"i":540,"p":34,"l":"Действие первое · явление четвертое","t":"Отказ Аргосу","d":"Отвергает требования Копрея: Афины свободный город и не выдадут молящих.","c":"Готов к войне ради закона богов.","k":true},{"i":700,"p":44,"l":"Действие второе · явление пятое","t":"Неразрешимое требование","d":"Сообщает Иолаю: прорицатели требуют в жертву Персефоне знатную деву, а своих дочерей он отдать не может.","c":"","k":false}]},{"id":"makariya","name":"Макария","role":"Дочь Геракла","intro":"Безымянная в трагедии «дева», добровольно идущая на смерть ради братьев.","arc":"Первая из добровольных жертв Еврипида (потом будут Менекей, Ифигения в Авлиде). Она выходит из храма, узнаёт об оракуле и сама предлагает себя, отказываясь от жребия.","st":[{"i":900,"p":57,"l":"Действие второе · явление шестое","t":"Добровольная жертва","d":"Узнав о требовании оракула, вызывается умереть, не желая, чтобы жребий решал за неё. Прощается с Иолаем и братьями.","c":"Смерть ради рода как акт свободы.","k":true}]},{"id":"alkmena","name":"Алкмена","role":"Мать Геракла, бабка Гераклидов","intro":"Старуха, чья ненависть к Еврисфею копилась годами.","arc":"Алкмена появляется как немощная старуха, но в финале становится грозной мстительницей: требует смерти пленного Еврисфея вопреки афинскому обычаю. Победа над врагом оборачивается новым нарушением закона.","st":[{"i":1096,"p":69,"l":"Действие третье · явление девятое","t":"Страх остаться одной","d":"Узнав, что Иолай идёт в бой, умоляет не покидать её и внуков.","c":"","k":false},{"i":1578,"p":100,"l":"Исход · явление тринадцатое","t":"Месть Еврисфею","d":"Видит пленного врага и требует его смерти, хотя афиняне не казнят пленных.","c":"Жертва превращается в мстителя.","k":true}],"gen":"Алкмена"},{"id":"evrisfey","name":"Еврисфей","role":"Царь Микен и Аргоса","intro":"Гонитель Геракла и его детей.","arc":"Еврисфей появляется только в финале, пленником. Он неожиданно достойно объясняет свои поступки страхом за собственную жизнь и предсказывает, что его могила станет защитой Афин от потомков Гераклидов.","st":[{"i":1578,"p":100,"l":"Исход · явление тринадцатое","t":"Пленник","d":"Спокойно принимает смерть и открывает пророчество: его прах будет оберегать Аттику.","c":"Враг становится хранителем.","k":true}],"gen":"Еврисфей"}]};
